TRUE = shutil.which("true") or "/bin/true"

# git-lfs, for the one test of a repo that uses it (#382); CI's runner image has it
GIT_LFS = subprocess.run(["git", "lfs", "version"], capture_output=True).returncode == 0


def home_outside_the_lane(test):
    """For a test that hides credentials under the home directory: the lane writes the temp roots
    whole, so with the home inside one (a sandbox's profile under /tmp) nothing there is hidden,
    and wb doctor and wb start say so (context.home_gap). Codex's run of 1.0 failed 11 of these
    (the 2026-11-19 audit)."""
    return unittest.skipIf(bool(context.home_gap()), "the home directory is inside a temp root, "
                           "which the lane writes whole (context.home_gap)")(test)


def lane_device():
    """A device node the lane would refuse, for a test that fakes the refusal: one this user may
    open (#773: one it may not is the user's own permissions, not the lane's, as on CI's runners
    with /dev/kvm in a group they're not in), and only where Landlock draws a lane."""
    if not lane.abi():
        return None
    return next((n for n in ("/dev/kvm", "/dev/fuse") if os.access(n, os.R_OK | os.W_OK)), None)


class Base(unittest.TestCase):
    def setUp(self):
        # `wb start` leaves its runner running on purpose (it outlives the command)
        warnings.simplefilter("ignore", ResourceWarning)
        self.tmp = tempfile.TemporaryDirectory()
        # its real path: macOS's temp directory is under /var, a link to /private/var, and wb
        # records repos and directories by their real paths (git's toplevel, getcwd)
        self.tmp.name = os.path.realpath(self.tmp.name)
        tmp = Path(self.tmp.name)
        self.env_before = dict(os.environ)
        # and again after every cleanup: a mock.patch.dict a test started (Lane.fake_home) stops
        # after tearDown and put this test's WB_* back, so a later class read its WB_GPU_DIR
        # (Privacy then test_portable's Optimize on Python 3.11, wave 2's merge, 2026-11-23)
        self.addCleanup(lambda: (os.environ.clear(), os.environ.update(self.env_before)))
        # the suite may run in Claude Code's Bash: no task is a session's unless a test says so
        os.environ.pop("CLAUDE_CODE_SESSION_ID", None)
        os.environ.pop("CLAUDE_PID", None)
        os.environ.pop("CLAUDECODE", None)  # wb patch send asks for the mod's yes under it (#1005)
        # the state directory before WB_HOME names it: a thread the last test left running (its
        # chat server) wrote there in between, and mkdir found it made (seen on WSL, 2026-11-20)
        (tmp / "state").mkdir()
        # self-review is on by default (tuning.py); the tests that count rounds don't want it
        (tmp / "state" / "tuning.json").write_text('{"self_review": 0}')
        os.environ.update(WB_HOME=str(tmp / "state"), WB_OPENCODE_BIN=FAKE, WB_FAKE_MODELS="1",
                          WB_OPENCODE_CONFIG=str(tmp / "opencode.json"),
                          WB_MODELS=str(tmp / "wb-models.json"), WB_SKILLS=str(tmp / "skills"),
                          WB_COMMANDS=str(tmp / "commands.json"),
                          # the roles (#1014): the test's own, never the user's routes.json
                          WB_ROUTES=str(tmp / "routes.json"),
                          # the GPU lease in the test's own state, never a machine's shared one (#393)
                          WB_GPU_DIR=str(tmp / "state"))
        (tmp / "opencode.json").write_text(json.dumps(OPENCODE_CONFIG))
        runner.models._AUTH.clear()  # OpenCode's stored keys, per process (models.auth_key)
        runner.models._STORED.clear()
        runner.models._KEYS.clear()
        # the config files' locks are outside WB_HOME, shared by every profile (#939): in the
        # test's own state, or the suite left thousands in the user's $XDG_RUNTIME_DIR
        lock_dir = mock.patch.object(store, "config_lock_dir", lambda: tmp / "state" / "locks")
        lock_dir.start()
        self.addCleanup(lock_dir.stop)
        self.repo = tmp / "repo"
        self.repo.mkdir()
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True)
        g("init", "-q", "-b", "main")
        (self.repo / "README.md").write_text("hello\n")
        (self.repo / "CLAUDE.md").write_text("# repo\nA test project.\n")  # wb start needs one
        g("add", ".")
        g("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "init")
        g("config", "user.email", "t@t")
        g("config", "user.name", "t")
        self.spec = tmp / "spec.md"
        self.spec.write_text("Write the answer to answer.txt.\n")

    def tearDown(self):
        # A runner still writing its last status races the rmtree (CI, 2026-11-17): let it finish.
        deadline = time.time() + 15
        while time.time() < deadline and any(cli.runner_alive(t) for t in store.all_tasks()):
            time.sleep(0.1)
        # A runner a failed test left running (blocked on a question, a hang) held CI's output open
        # until the job was cancelled, 15 minutes after the suite ended (#141): stop it.
        for t in store.all_tasks():
            if cli.runner_alive(t):
                cli._stop_runner(t)
        for t in store.all_tasks():  # the agents' runtime directories are in /tmp, not the state
            context.drop_runtime_dir(t)
        os.environ.clear()
        os.environ.update(self.env_before)
        self.tmp.cleanup()

    def start(self, name, scenario, *extra):
        os.environ["FAKE_SCENARIO"] = scenario
        return run_wb("start", name, "--spec", str(self.spec), "--repo", str(self.repo),
                      "--model", "mimo", *extra)


class Lifecycle(Base):
    def test_ok_round_passes_tests_and_accepts(self):
        self.start("t-ok", "ok", "--test", TEST_CMD)
        st = wait_phase("t-ok", {"review"})
        self.assertTrue(st["tests"]["ok"])
        self.assertTrue(st["session"].startswith("ses_"))
        report = run_wb("report", "t-ok")
        self.assertIn("tests: PASS", report)
        self.assertIn("answer.txt", report)
        self.assertIn("+42", run_wb("diff", "t-ok"))
        # the review notification is delivered once; a later wait says it was
        self.assertIn("[review] t-ok", run_wb("wait", "t-ok", "--timeout", "1"))
        self.assertIn("already delivered", run_wb("wait", "t-ok", "--timeout", "1"))
        out = run_wb("accept", "t-ok", "-m", "feat: answer", "--merge")
        self.assertIn("merged", out)
        # #269 (the audit of 1.2): read at the deleted branch, every merged accept said this
        self.assertNotIn("no CLAUDE.md", out)
        self.assertRegex(out, r"CLAUDE\.md (is current with|last changed \d+ commit\(s\) before) [0-9a-f]{7}")
        self.assertEqual((self.repo / "answer.txt").read_text(), "42\n")
        log = subprocess.run(["git", "-C", str(self.repo), "log", "--format=%B", "-n1",
                              store.Task("t-ok").status["tip"]], capture_output=True, text=True).stdout
        self.assertIn("Workbench-Task: t-ok", log)
        self.assertIn("OpenCode-Session: ses_", log)
        self.assertNotIn("Co-Authored-By", log)   # the user's commit; no AI credit line
        rows, _ = store.read_jsonl(store.home() / "results.jsonl")
        self.assertEqual(rows[-1]["outcome"], "accepted")

    def test_a_feedback_round_says_feedback_in_round_for(self):
        # #1048: the pane's stage says why a round runs (`round 2 · feedback 1`); the round number
        # alone told a feedback round from an auto-fix, a steer or a fresh session by nothing
        self.start("t-rfb", "fix", "--test", TEST_CMD, "--auto-fix", "0")
        first = wait_phase("t-rfb", {"review"})
        self.assertEqual((first["round"], first["round_for"]), (1, "start"))
        run_wb("feedback", "t-rfb", "--text", "1. The answer is 42.")
        st = wait_phase("t-rfb", {"review"})
        self.assertEqual((st["round"], st["reviews"], st["round_for"]), (2, 1, "feedback"))

    def test_a_self_review_a_next_step_and_a_resume_each_say_why_in_round_for(self):
        # #1048: the rest of the round kinds the pane names (`self-review`, `step 2`, `resumed`)
        self.start("t-rself", "ok", "--test", TEST_CMD, "--no-base-check", "--self-review")
        st = wait_phase("t-rself", {"review"})
        self.assertEqual((st["round"], st["round_for"]), (2, "self_review"))
        self.start("t-rkind", "ok", "--test", TEST_CMD, "--no-base-check", "--no-self-review")
        wait_phase("t-rkind", {"review"})
        run_wb("next", "t-rkind", "--spec", str(self.spec), "-m", "feat: step one")
        st = wait_phase("t-rkind", {"review"})
        self.assertEqual((st["steps"], st["round"], st["round_for"]), (2, 2, "next"))
        task = store.Task("t-rkind")
        task.set_status(phase="stuck", last="stopped by the reviewer")    # as wb stop leaves it
        run_wb("resume", "t-rkind")
        st = wait_phase("t-rkind", {"review"})
        self.assertEqual((st["round"], st["round_for"]), (3, "resume"))

    def test_a_task_resumed_before_its_first_round_says_resume_in_round_for(self):
        # #1048: wb resume's other path (it never ran a round: round 1 again) names its round too
        with mock.patch.object(cli, "spawn_runner"):
            self.start("t-rfirst", "ok", "--no-self-review")
        with mock.patch.object(runner, "_down", return_value=True), \
                mock.patch.object(runner, "_wait_up", side_effect=RuntimeError("the server is down")):
            runner.drive(store.Task("t-rfirst"))
        self.assertEqual(store.Task("t-rfirst").status["round_for"], "start")
        with mock.patch.object(cli, "spawn_runner"):
            self.assertIn("its first round, which it never ran", run_wb("resume", "t-rfirst"))
        st = store.Task("t-rfirst").status
        self.assertEqual((st["phase"], st["round"], st["round_for"]), ("queued", 1, "resume"))

    def test_a_round_start_records_the_typical_length_and_how_many_tasks_back_it(self):
        # #1048: the pane sets a task's active work against its typical length (`~6m left`) with
        # no read of results.jsonl of its own, and only when enough timed tasks back it
        model = "ollama/mimo-v2.6:9b-q8_0"
        for mins in (12, 14, 30):
            store.append_jsonl(store.home() / "results.jsonl", {
                "model": model, "size": "significant", "outcome": "accepted", "active_minutes": mins})
        self.start("t-typ", "ok")
        st = wait_phase("t-typ", {"review"})
        self.assertEqual(store.Task("t-typ").spec["model"], model)
        self.assertEqual(st["typical"], {"min": 14, "n": 3})

    def test_no_history_writes_no_typical(self):
        self.start("t-notyp", "ok")
        self.assertNotIn("typical", wait_phase("t-notyp", {"review"}))
        self.assertNotIn("late_min", store.Task("t-notyp").status)  # the size's default: no point

    def test_a_task_is_late_only_from_the_progress_checks_own_point(self):
        # step A's review (#1048): a median of 4 minutes coloured a 5-minute task late, where no
        # progress check would come before FLOOR_MIN; the user's --after moves the point
        model = "ollama/mimo-v2.6:9b-q8_0"
        for mins in (3, 4, 5):
            store.append_jsonl(store.home() / "results.jsonl", {
                "model": model, "size": "significant", "outcome": "accepted", "active_minutes": mins})
        with mock.patch.object(cli, "spawn_runner"):
            self.start("t-late", "ok")
        task = store.Task("t-late")
        self.assertEqual(runner.typical_now(task), {"typical": {"min": 4, "n": 3},
                                                    "late_min": progress.FLOOR_MIN})
        progress.set_enabled(True, after=30)
        self.assertEqual(runner.typical_now(task)["late_min"], 30)

    def test_an_api_task_whose_model_hosted_json_lacks_gets_no_typical(self):
        # step A's review (#1048): with no model found to time, the pane shows no estimate
        with mock.patch.object(cli, "spawn_runner"):
            self.start("t-apityp", "ok")
        task = store.Task("t-apityp")
        spec = dict(task.spec, model="deepseek/no-such-model", via="api", provider="deepseek")
        store.write_json(task.dir / "task.json", spec)
        for mins in (12, 14, 30):
            store.append_jsonl(store.home() / "results.jsonl", {
                "model": spec["model"], "kind": "api", "size": "significant", "outcome": "accepted",
                "active_minutes": mins})
        self.assertEqual(runner.typical_now(store.Task("t-apityp")), {})

    def drive_here(self, name: str) -> store.Task:
        """A task's runner driven in this process, so a test's patches reach it."""
        with mock.patch.object(cli, "spawn_runner"):
            self.start(name, "ok", "--no-self-review", "--no-base-check")
        runner.drive(store.Task(name))
        return store.Task(name)

    def test_a_task_on_one_card_of_two_records_its_card(self):
        # #1048: the pane's `GPU 1` tells two tasks on two cards apart
        two = [{"name": "card", "discrete": True, "uuid": "GPU-a"}, {"name": "card", "discrete": True, "uuid": "GPU-b"}]
        with mock.patch.object(runner.models, "card_numbers", return_value=[1]), \
                mock.patch.object(runner.hardware, "gpus", return_value=two):
            st = self.drive_here("t-card1").status
        self.assertEqual((st["phase"], st["cards"]), ("review", [1]))

    def test_a_one_card_machine_records_no_cards(self):
        one = [{"name": "card", "discrete": True, "uuid": "GPU-a"}]
        with mock.patch.object(runner.models, "card_numbers", return_value=[0]), \
                mock.patch.object(runner.hardware, "gpus", return_value=one):
            st = self.drive_here("t-card0").status
        self.assertEqual(st["phase"], "review")
        self.assertNotIn("cards", st)  # `GPU`, with no noise

    def test_an_api_task_records_no_cards(self):
        with mock.patch.object(cli, "spawn_runner"):
            self.start("t-cardapi", "ok")
        task = store.Task("t-cardapi")
        m = runner.models.discover()[task.spec["model"]]
        with mock.patch.object(runner.models, "card_numbers", return_value=[1]) as cards:
            self.assertEqual(runner.cards_now(task, dataclasses.replace(m, kind="api")), {})
            self.assertEqual(runner.cards_now(task, dataclasses.replace(m, remote=True)), {})
            cards.assert_not_called()
            # a later runner that can't tell clears what an earlier one wrote
            task.set_status(cards=[1])
            self.assertEqual(runner.cards_now(task, dataclasses.replace(m, kind="api")), {"cards": None})

    def test_a_card_or_record_that_cant_be_read_still_runs_the_round(self):
        # the #1048 merge review: the pane's label and estimate are read at the lease and the round's
        # start, and a raise there failed the round for a fact only the pane shows
        with mock.patch.object(runner.models, "card_numbers", side_effect=OSError("sysfs")), \
                mock.patch("workbench.router.expected", side_effect=ValueError("bad row")):
            st = self.drive_here("t-cardraise").status
        self.assertEqual(st["phase"], "review")
        self.assertNotIn("cards", st)
        self.assertNotIn("typical", st)

    def test_start_refuses_when_opencode_isnt_on_path_and_leaves_nothing(self):
        # the 2026-11-16 audit: the runner emptied the GPU, then the round died as "opencode exited 1"
        os.environ["WB_OPENCODE_BIN"] = "wb-no-such-opencode run"
        err = io.StringIO()
        with self.assertRaises(SystemExit), redirect_stderr(err):
            self.start("t-nooc", "ok")
        self.assertIn("wb-no-such-opencode isn't on PATH", err.getvalue())
        self.assertFalse(store.Task("t-nooc").dir.exists())

    def test_start_returns_at_once_and_the_runner_checks_the_base(self):
        # The base check ran inside wb start, which a slow suite pushed past Claude's two-minute
        # Bash limit, leaving a task queued with no runner (the 2026-11-16 audit).
        os.environ["FAKE_SLEEP"] = "1"
        began = time.time()
        out = self.start("t-base", "ok", "--test", TEST_CMD)
        self.assertLess(time.time() - began, 10)
        self.assertIn("base check: the runner runs the acceptance command", out)
        st = wait_phase("t-base", {"review"})
        self.assertIs(st["base_check"]["ok"], False)
        self.assertTrue((store.Task("t-base").dir / "base-tests.txt").exists())
        report = run_wb("report", "t-base")
        self.assertIn("on the base the acceptance command fails (exit", report)
        self.assertIn("check the tail shows it failing only for what the step changes", report)
        self.assertIn("on the base the acceptance command fails", run_wb("wait", "t-base", "--timeout", "1"))

    def test_the_base_check_line_promises_a_check_in_only_for_a_cut_short_run(self):
        # #881 (Claude's audit of 1.90.24): it promised a check-in when the command already
        # passes on the base, which the runner never raises (a note in the first report)
        out = self.start("t-bline", "ok", "--test", "true")
        line = next(x for x in out.splitlines() if x.startswith("base check:"))
        self.assertIn("a check-in at once if --test-timeout cuts it short", line)
        self.assertNotIn("already passes", line)
        wait_phase("t-bline", {"review"})
        self.assertNotIn("checkin", [r["kind"] for r in store.notices() if r["task"] == "t-bline"])

    def test_what_the_base_check_writes_never_reaches_the_agents_worktree(self):
        # #192 (the 2026-11-19 audit): the base check ran in the task's worktree, and a stamp it
        # wrote made the same failing command pass after the agent's unrelated edit
        cmd = "test -f build.stamp || { touch build.stamp; exit 1; }"
