    def test_a_merge_into_a_branch_that_lost_the_base_is_refused_with_what_would_come_back(self):
        # #418 (the audit of 1.8, reproduced): main reset back past the task's base, then accept
        # --merge into main (its base_branch) brought the withdrawn commit back; only a merge into
        # the checkout's branch with no base_branch recorded was held to the base
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True, text=True).stdout.strip()
        def withdrawn_then(name, rewrite):
            (self.repo / "withdrawn.txt").write_text("taken back\n")
            g("add", "withdrawn.txt")
            g("commit", "-qm", f"withdrawn for {name}")
            self.start(name, "ok")
            wait_phase(name, {"review"})
            self.assertEqual(store.Task(name).spec["base_branch"], "main")
            rewrite()
            before = g("rev-parse", "main")
            with redirect_stderr(io.StringIO()) as err:
                not_merged("accept", name, "-m", "feat: answer", "--merge")
            self.assertIn("doesn't hold the task's base", err.getvalue(), name)
            self.assertIn(f"withdrawn for {name}", err.getvalue(), name)  # what would come back
            self.assertIn("rebase --onto main", err.getvalue(), name)     # and the choices
            self.assertIn("by hand", err.getvalue(), name)
            self.assertEqual(g("rev-parse", "main"), before, name)
            self.assertFalse((self.repo / "withdrawn.txt").exists(), name)
            self.assertTrue(self.branch(f"delegate/{name}"), name)        # the work is kept
        withdrawn_then("t-rewound", lambda: g("reset", "-q", "--hard", "HEAD~1"))
        def rebased():  # the withdrawn commit rewritten: a force-pushed main, pulled down
            g("reset", "-q", "--hard", "HEAD~1")
            (self.repo / "other.txt").write_text("rebased in\n")
            g("add", "other.txt")
            g("commit", "-qm", "the rebased history")
        withdrawn_then("t-rebased", rebased)
        self.start("t-forward", "ok")  # main moving forward still merges
        wait_phase("t-forward", {"review"})
        (self.repo / "later.txt").write_text("later\n")
        g("add", "later.txt")
        g("commit", "-qm", "later work on main")
        self.assertIn("merged into main", run_wb("accept", "t-forward", "-m", "feat: answer", "--merge"))
        self.assertEqual((self.repo / "answer.txt").read_text().strip(), "42")

    def test_a_colocated_jujutsu_repo_is_told_to_merge_with_jj(self):
        # #385 (the audit of 1.6): jj keeps git's HEAD detached once it has moved the working
        # copy, so accept --merge refused "a detached HEAD" and offered a git merge, whose commit
        # a detached HEAD orphans. Built from what git sees of a colocated repo (jj 0.47.1's: a
        # .jj/ beside .git, ignoring itself, and HEAD detached at the working copy's parent),
        # with no jj needed
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True)
        (self.repo / ".jj" / "repo").mkdir(parents=True)
        (self.repo / ".jj" / ".gitignore").write_text("/*\n")
        g("switch", "-q", "--detach", "main")
        self.start("t-jj", "ok")
        st = store.Task("t-jj")
        self.assertIsNone(st.spec["base_branch"])
        wait_phase("t-jj", {"review"})
        err = io.StringIO()
        with redirect_stderr(err):
            out = not_merged("accept", "t-jj", "-m", "feat: answer", "--merge")
        self.assertIn("colocated Jujutsu repo", err.getvalue())
        self.assertIn(f"merge with: jj -R {self.repo} new @- delegate/t-jj", out)
        self.assertNotIn("git -C", out)
        # a branch recorded at start (--base main), with jj's detached HEAD out at accept
        self.start("t-jj2", "ok", "--base", "main")
        self.assertEqual(store.Task("t-jj2").spec["base_branch"], "main")
        wait_phase("t-jj2", {"review"})
        with redirect_stderr(err):
            not_merged("accept", "t-jj2", "-m", "feat: answer", "--merge")
        self.assertIn("merge delegate/t-jj2 with jj: jj -R", err.getvalue())
        self.assertEqual(g("rev-parse", "HEAD").stdout, g("rev-parse", "main").stdout)

    def test_an_ignored_file_in_the_checkout_survives_an_accept_merge(self):
        # #189 (the 2026-11-19 audit): the task un-ignored settings.ini and committed a default,
        # and accept --merge replaced the user's own copy (git's merge overwrites ignored files)
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True, text=True).stdout.strip()
        (self.repo / ".gitignore").write_text("settings.ini\n")
        g("add", ".gitignore")
        g("commit", "-qm", "ignore settings")
        (self.repo / "settings.ini").write_text("PERSONAL\n")
        before = g("rev-parse", "main")
        self.start("t-ign", "ok")
        wait_phase("t-ign", {"review"})
        wt = store.Task("t-ign").worktree
        (wt / ".gitignore").write_text("")
        (wt / "settings.ini").write_text("DEFAULT\n")
        err = io.StringIO()
        with redirect_stderr(err):
            out = not_merged("accept", "t-ign", "-m", "feat: default settings", "--merge")
        self.assertIn("not merged", err.getvalue())
        self.assertIn("settings.ini", err.getvalue())             # git names the file in the way
        self.assertEqual((self.repo / "settings.ini").read_text(), "PERSONAL\n")
        self.assertEqual(g("rev-parse", "main"), before)          # main untouched
        self.assertEqual(g("show", "delegate/t-ign:settings.ini"), "DEFAULT")  # the work is kept
        self.assertIn("merge with: git", out)
        self.assertFalse(subprocess.run(["git", "-C", str(self.repo), "rev-parse", "-q", "--verify",
                                         "MERGE_HEAD"], capture_output=True).returncode == 0)

    def _merge_case(self, base, main, task, ignore, config=()):
        """A repo whose task branch and main each made their commits from one base; the
        ignored files are written last, as the developer's own. Returns (repo, git)."""
        repo = Path(self.tmp.name) / f"m{len(os.listdir(self.tmp.name))}"
        repo.mkdir()
        g = lambda *a: subprocess.run(["git", "-C", str(repo), *a], check=True,  # noqa
                                      capture_output=True).stdout
        g("init", "-q", "-b", "main")
        for k, v in config:
            g("config", k, v)
        def commit(files, msg):
            for name, data in files.items():
                f = repo / os.fsdecode(name)
                if data is None:
                    g("rm", "-q", "--cached", "--", os.fsdecode(name))
                    f.unlink(missing_ok=True)  # pkg's file gone, so pkg/ can be made (#343)
                    if f.parent != repo and not any(f.parent.iterdir()):
                        f.parent.rmdir()       # and pkg/ gone, so pkg can be (#343)
                    continue
                f.parent.mkdir(parents=True, exist_ok=True)
                f.write_bytes(data)
                g("add", "--", os.fsdecode(name))
            g("commit", "-qm", msg)
        commit(base, "base")
        g("switch", "-qc", "delegate/t")
        commit(task, "task")
        g("switch", "-q", "main")
        commit(main, "main")
        for name, data in ignore.items():
            (repo / os.fsdecode(name)).parent.mkdir(parents=True, exist_ok=True)
            (repo / os.fsdecode(name)).write_bytes(data)
        return repo, g

    def _assert_refused_and_kept(self, repo, g, path, data):
        before = g("rev-parse", "main")
        with self.assertRaises(gitops.GitError) as e:
            gitops.merge(repo, "t", "main")
        self.assertIn("would overwrite", str(e.exception))
        self.assertEqual((repo / os.fsdecode(path)).read_bytes(), data)  # byte for byte
        self.assertEqual(g("rev-parse", "main"), before)
        self.assertNotEqual(subprocess.run(["git", "-C", str(repo), "rev-parse", "-q", "--verify",
                                            "MERGE_HEAD"], capture_output=True).returncode, 0)
        g("rev-parse", "--verify", "delegate/t")                         # the work is kept

    def test_a_modify_delete_conflict_leaves_the_ignored_personal_copy(self):
        # #241 (the audit of 1.2, reproduced): main stopped tracking settings.ini and the
        # developer kept an ignored copy; the task edited the tracked one. The merge conflicted,
        # its abort deleted the copy, and wb said "backed out"
        repo, g = self._merge_case(
            base={b"settings.ini": b"DEFAULT\n"},
            main={b"settings.ini": None, b".gitignore": b"settings.ini\n"},
            task={b"settings.ini": b"DEFAULT\nmore\n"},
            ignore={b"settings.ini": b"PERSONAL\n"})
        self._assert_refused_and_kept(repo, g, b"settings.ini", b"PERSONAL\n")

    def test_a_directory_rename_does_not_move_an_added_file_onto_an_ignored_one(self):
        # #241: main renamed conf/ to etc/, where the developer keeps an ignored local.cfg; the
        # task added conf/local.cfg, which merge.directoryRenames moves to etc/local.cfg
        repo, g = self._merge_case(
            base={b"conf/a.cfg": b"a\n", b"conf/b.cfg": b"b\n"},
            main={b"conf/a.cfg": None, b"conf/b.cfg": None, b"etc/a.cfg": b"a\n",
                  b"etc/b.cfg": b"b\n", b".gitignore": b"etc/local.cfg\n"},
            task={b"conf/local.cfg": b"TASK\n"},
            ignore={b"etc/local.cfg": b"PERSONAL\n"},
            config=[("merge.directoryRenames", "true")])
        (repo / "conf").exists() and shutil.rmtree(repo / "conf")
        self._assert_refused_and_kept(repo, g, b"etc/local.cfg", b"PERSONAL\n")

    def test_a_file_name_that_is_not_utf8_is_checked_as_its_bytes(self):
        # #241: the path list was decoded with U+FFFD, so a Latin-1 name missed the check
        name = b"r\xe9glages.ini"
        try:
            repo, g = self._merge_case(
                base={b"README": b"x\n"}, main={b".gitignore": name + b"\n"},
                task={name: b"TASK\n"}, ignore={name: b"PERSONAL\n"})
        except (OSError, subprocess.CalledProcessError) as e:  # APFS takes UTF-8 names only
            if getattr(e, "errno", errno.EILSEQ) != errno.EILSEQ:
                raise
            self.skipTest("this file system refuses names that aren't UTF-8")
        self._assert_refused_and_kept(repo, g, name, b"PERSONAL\n")

    def test_on_a_git_before_2_38_the_merge_is_tried_in_a_scratch_worktree_first(self):
        # #320 (the audit of 1.4, reproduced on Git 2.34.1): without merge-tree --write-tree the
        # check read only the paths the branch adds, missed the modify/delete conflict, and the
        # abort deleted the personal copy. The cases above, with that git's answer
        cases = [
            (dict(base={b"settings.ini": b"DEFAULT\n"},
                  main={b"settings.ini": None, b".gitignore": b"settings.ini\n"},
                  task={b"settings.ini": b"DEFAULT\nmore\n"},
                  ignore={b"settings.ini": b"PERSONAL\n"}), b"settings.ini"),
            (dict(base={b"conf/a.cfg": b"a\n", b"conf/b.cfg": b"b\n"},
                  main={b"conf/a.cfg": None, b"conf/b.cfg": None, b"etc/a.cfg": b"a\n",
                        b"etc/b.cfg": b"b\n", b".gitignore": b"etc/local.cfg\n"},
                  task={b"conf/local.cfg": b"TASK\n"},
                  ignore={b"etc/local.cfg": b"PERSONAL\n"},
                  config=[("merge.directoryRenames", "true")]), b"etc/local.cfg"),
        ]
        with mock.patch.object(gitops, "_merge_tree", return_value=None):
            for case, path in cases:
                repo, g = self._merge_case(**case)
                (repo / "conf").exists() and shutil.rmtree(repo / "conf")
                self._assert_refused_and_kept(repo, g, path, b"PERSONAL\n")
                self.assertEqual(g("worktree", "list", "--porcelain").count(b"worktree "), 1,
                                 "the scratch worktree is gone")
            repo, g = self._merge_case(
                base={b"a.txt": b"a\n"}, main={b".gitignore": b"local.ini\n"},
                task={b"b.txt": b"b\n"}, ignore={b"local.ini": b"PERSONAL\n"})
            gitops.merge(repo, "t", "main")  # nothing in the way: it still merges
            self.assertEqual((repo / "b.txt").read_bytes(), b"b\n")
            self.assertEqual((repo / "local.ini").read_bytes(), b"PERSONAL\n")

    def test_on_a_git_before_2_38_the_trial_merge_writes_only_the_files_it_changes(self):
        # #469 (the audit of 1.8): the trial worktree was a full checkout of HEAD, gigabytes and
        # minutes on a big repo, running LFS's smudge on every file. A smudge filter logs what
        # was checked out: the file nobody touched never is, and the trial skips LFS's smudge
        log = Path(self.tmp.name) / "smudged.log"
        smudge = f"sh -c 'echo \"%f ${{GIT_LFS_SKIP_SMUDGE:-}}\" >> {shlex.quote(str(log))}; cat'"
        repo, g = self._merge_case(
            base={b".gitattributes": b"*.big filter=wbt\n", b"untouched.big": b"U\n",
                  b"a.txt": b"1\n2\n3\n4\n"},
            main={b"a.txt": b"1\n2\n3\nfour\n"}, task={b"a.txt": b"one\n2\n3\n4\n",
                                                     b"changed.big": b"C\n"},
            ignore={}, config=[("filter.wbt.smudge", smudge)])
        log.unlink(missing_ok=True)
        with mock.patch.object(gitops, "_merge_tree", return_value=None):
            gitops.merge(repo, "t", "main")
        self.assertEqual((repo / "a.txt").read_bytes(), b"one\n2\n3\nfour\n")
        smudged = log.read_text().splitlines()
        self.assertNotIn("untouched.big", " ".join(smudged))
        self.assertIn("changed.big 1", smudged)  # the trial's, LFS skipped
        self.assertEqual(g("worktree", "list", "--porcelain").count(b"worktree "), 1)

    def test_a_case_only_rename_merges_on_a_case_insensitive_file_system(self):
        # #470 (the audit of 1.8): renaming Readme.md to README.md, lexists("README.md") is true
        # on APFS, and the merge was refused as "would overwrite README.md". The file system is
        # made case-insensitive for the check: README.md is a second name for Readme.md's inode,
        # as APFS gives it, and core.ignorecase says so (#640: the inode decides, not the setting)
        repo, g = self._merge_case(
            base={b"Readme.md": b"r\n", b"a.txt": b"a\n"}, main={b"a.txt": b"A\n"},
            task={b"Readme.md": None, b"README.md": b"r\n"}, ignore={})
        g("config", "core.ignorecase", "true")
        real = os.path.lexists

        def lexists(path):
            path = os.fsdecode(path)
            parent, name = os.path.split(path)
            return real(path) or os.path.isdir(parent) and any(
                n.casefold() == name.casefold() for n in os.listdir(parent))
        made = not os.path.lexists(repo / "README.md")  # on macOS's APFS it is already (#950)
        if made:
            os.link(repo / "Readme.md", repo / "README.md")
        for old_git in (False, True):
            with mock.patch.object(gitops, "_merge_tree", return_value=None) if old_git \
                    else nullcontext():
                self.assertEqual(gitops._overwritten(repo, "delegate/t"), [])
        if made:
            (repo / "README.md").unlink()
        gitops.merge(repo, "t", "main")
        self.assertEqual((repo / "README.md").read_bytes(), b"r\n")
        repo, g = self._merge_case(  # a case-sensitive git: in the way, as before
            base={b"Readme.md": b"r\n"}, main={b"a.txt": b"A\n"},
            task={b"Readme.md": None, b"README.md": b"r\n"}, ignore={})
        g("config", "core.ignorecase", "false")  # git init sets it true on macOS
        with mock.patch("os.path.lexists", lexists):
            self.assertEqual(gitops._overwritten(repo, "delegate/t"), ["README.md"])

    @unittest.skipIf(gitops._case_folds(tempfile.gettempdir()),
                     "the temp directory's file system folds case (macOS's APFS): CONFIG and "
                     "config can't both exist there")
    def test_a_stale_ignorecase_on_a_case_sensitive_file_system_keeps_the_ignored_twin(self):
        # #640 (Codex's audit of 1.90.6): a copied repo carried core.ignorecase=true onto a
        # case-sensitive file system; the checkout tracked CONFIG and kept its own ignored config,
        # the task committed config, and the guard took the two names for one file: the merge
        # replaced the personal file
        repo, g = self._merge_case(
            base={b"CONFIG": b"tracked\n"}, main={b".gitignore": b"config\n"},
            task={b"config": b"DEFAULT\n"}, ignore={b"config": b"PERSONAL\n"})
        g("config", "core.ignorecase", "true")  # carried over with the copy
        self.assertEqual((repo / "CONFIG").read_bytes(), b"tracked\n")  # two files here
        for old_git in (False, True):
            with mock.patch.object(gitops, "_merge_tree", return_value=None) if old_git \
                    else nullcontext():
                self.assertEqual(gitops._overwritten(repo, "delegate/t"), ["config"])
        self._assert_refused_and_kept(repo, g, b"config", b"PERSONAL\n")

    def test_a_clean_merge_beside_ignored_files_still_merges(self):
        repo, g = self._merge_case(
            base={b"a.txt": b"a\n"}, main={b".gitignore": b"local.ini\n"},
            task={b"b.txt": b"b\n"}, ignore={b"local.ini": b"PERSONAL\n"})
        gitops.merge(repo, "t", "main")
        self.assertEqual((repo / "b.txt").read_bytes(), b"b\n")
        self.assertEqual((repo / "local.ini").read_bytes(), b"PERSONAL\n")

    def test_a_file_turned_into_a_directory_and_back_merges_beside_ignored_files(self):
        # #343 (the audit of 1.4, reproduced on Git 2.56): the task replaced the tracked file pkg
        # with pkg/init.py, and accept --merge called pkg an untracked obstruction; a plain git
        # merge of the kept branch succeeded. Both directions, beside real ignored files
        for old_git in (False, True):
            with (mock.patch.object(gitops, "_merge_tree", return_value=None) if old_git
                  else contextlib.nullcontext()):
                repo, g = self._merge_case(
                    base={b"pkg": b"one\n"}, main={b".gitignore": b"*.pyc\nlocal.ini\n"},
                    task={b"pkg": None, b"pkg/init.py": b"two\n"},
                    ignore={b"local.ini": b"PERSONAL\n", b"x.pyc": b"c"})
                gitops.merge(repo, "t", "main")
                self.assertEqual((repo / "pkg" / "init.py").read_bytes(), b"two\n")
                self.assertEqual((repo / "local.ini").read_bytes(), b"PERSONAL\n")
                repo, g = self._merge_case(
                    base={b"pkg/init.py": b"one\n"}, main={b".gitignore": b"local.ini\n"},
                    task={b"pkg/init.py": None, b"pkg": b"two\n"},
                    ignore={b"local.ini": b"PERSONAL\n"})
                gitops.merge(repo, "t", "main")
                self.assertEqual((repo / "pkg").read_bytes(), b"two\n")
                self.assertEqual((repo / "local.ini").read_bytes(), b"PERSONAL\n")
                # an ignored file inside the directory the merge turns into a file is in the way
                repo, g = self._merge_case(
                    base={b"pkg/init.py": b"one\n"}, main={b".gitignore": b"*.pyc\n"},
                    task={b"pkg/init.py": None, b"pkg": b"two\n"},
                    ignore={b"pkg/init.pyc": b"PERSONAL\n"})
                self._assert_refused_and_kept(repo, g, b"pkg/init.pyc", b"PERSONAL\n")

    def test_a_merge_never_replaces_an_ignored_link_it_would_write_under(self):
        # #367 (the audit of 1.6, reproduced on Git 2.56): the user's ignored `data`, a link to a
        # dataset elsewhere, became a plain directory holding only the task's added.txt
        outside = Path(self.tmp.name) / "dataset"
        outside.mkdir()
        (outside / "keep.txt").write_text("KEEP\n")
        (Path(self.tmp.name) / "notes.txt").write_text("NOTES\n")
        for target in (outside, Path(self.tmp.name) / "notes.txt", Path("src")):  # dir, file, tracked dir
            repo, g = self._merge_case(base={b"src/x.py": b"x\n", b".gitignore": b"data\n"},
                                       main={b"c.txt": b"c\n"},
                                       task={b".gitignore": b"", b"data/added.txt": b"new\n"}, ignore={})
            (repo / "data").symlink_to(target)
            before = g("rev-parse", "main")
            with self.assertRaises(gitops.GitError) as e:
                gitops.merge(repo, "t", "main")
            self.assertIn("would overwrite", str(e.exception))
            self.assertIn("data", str(e.exception))
            self.assertTrue((repo / "data").is_symlink())                   # still the link
            self.assertEqual(os.readlink(repo / "data"), str(target))
            self.assertEqual(g("rev-parse", "main"), before)
        self.assertEqual(sorted(p.name for p in outside.iterdir()), ["keep.txt"])

    def test_a_merge_as_ff_or_squash_keeps_the_history_linear(self):
        # #352 (the audit of 1.4): --no-ff made a merge commit a linear-history repo refused
        git = lambda r, *a: subprocess.run(["git", "-C", str(r), *a], check=True,  # noqa
                                           capture_output=True, text=True).stdout.strip()
        repo, g = self._merge_case(base={b"a.txt": b"a\n"}, main={b"c.txt": b"c\n"},
                                   task={b"b.txt": b"b\n"}, ignore={})
        tip = git(repo, "rev-parse", gitops.branch_name("t"))
        with self.assertRaisesRegex(gitops.GitError, "backed out"):  # main moved: no ff
            gitops.merge(repo, "t", "main", how="ff")
        head = gitops.merge(repo, "t", "main", how="squash")
        self.assertEqual(git(repo, "rev-list", "--min-parents=2", "--count", "HEAD"), "0")
        self.assertEqual((repo / "b.txt").read_bytes(), b"b\n")
        self.assertEqual(git(repo, "log", "-1", "--format=%s", head), git(repo, "log", "-1",
                                                                         "--format=%s", tip))
        git(repo, "reset", "-q", "--hard", f"{tip}~1")  # the base: a fast-forward lands the tip
        self.assertTrue(tip.startswith(gitops.merge(repo, "t", "main", how="ff")))
        self.assertEqual(git(repo, "rev-list", "--min-parents=2", "--count", "HEAD"), "0")

    def test_a_squash_lands_under_merge_ff_only_and_merge_ff_false(self):
        # #429 (the audit of 1.8, reproduced): merge.ff=only refused every squash once main had
        # moved ("Not possible to fast-forward"), merge.ff=false every squash at all ("'--squash'
        # and '--no-ff' cannot be used together"): the linear-history repos #352 was made for
        for ff in ("only", "false"):
            repo, g = self._merge_case(base={b"a.txt": b"a\n"}, main={b"c.txt": b"c\n"},
                                       task={b"b.txt": b"b\n"}, ignore={}, config=[("merge.ff", ff)])
            head = gitops.merge(repo, "t", "main", how="squash")
            self.assertEqual((repo / "b.txt").read_bytes(), b"b\n", ff)
            self.assertEqual(g("rev-list", "--min-parents=2", "--count", "HEAD"), b"0\n", ff)
            self.assertEqual(g("rev-parse", "--short", "HEAD").strip().decode(), head, ff)
            self.assertEqual(g("status", "--porcelain"), b"", ff)

    def test_no_merge_mode_runs_the_repos_hooks_and_the_merge_commit_names_the_branch(self):
        # #499 (Claude's audit of 1.90, reproduced): a commit-msg hook requiring "feat: " refused
        # the merge's "Merge commit '<sha>'", which nobody could edit, and accept exited 5, while
        # --merge-as squash ran no hooks and landed; #471: the message named a raw SHA
        hooks = Path(self.tmp.name) / "hooks"
        hooks.mkdir()
        mark = Path(self.tmp.name) / "hook-ran"
        for name in ("commit-msg", "pre-merge-commit", "post-merge", "pre-commit"):
            (hooks / name).write_text(f"#!/bin/sh\necho {name} >> {mark}\nexit 1\n")
            (hooks / name).chmod(0o755)
        for how in ("merge", "squash", "ff"):
            repo, g = self._merge_case(base={b"a.txt": b"a\n"}, main={b"c.txt": b"c\n"},
                                       task={b"b.txt": b"b\n"}, ignore={})
            if how == "ff":
                g("reset", "-q", "--hard", "HEAD~1")
            g("config", "core.hooksPath", str(hooks))
            tip = g("rev-parse", "delegate/t").strip().decode()  # what accept merges: the SHA
            gitops.merge(repo, "t", "main", how=how, tip=tip)
            self.assertEqual((repo / "b.txt").read_bytes(), b"b\n", how)
            self.assertFalse(mark.exists(), mark.exists() and mark.read_text())
            if how == "merge":
                self.assertEqual(g("log", "-1", "--format=%s"), b"Merge branch 'delegate/t'\n")
                g("switch", "-q", "-c", "dev", "HEAD~1")  # git's own wording: "into dev" here
                g("config", "merge.log", "true")          # and its shortlog, once
                gitops.merge(repo, "t", "dev", tip=tip)
                self.assertEqual(g("log", "-1", "--format=%B"),
                                 b"Merge branch 'delegate/t' into dev\n\n* delegate/t:\n  task\n\n")

    def _submodule_case(self):
        """A repo with submodule lib, a task branch adding b.txt, and main moved on."""
        top = Path(self.tmp.name) / f"s{len(os.listdir(self.tmp.name))}"
        top.mkdir()
        g = lambda r, *a: subprocess.run(["git", "-C", str(r), *a], check=True,  # noqa
                                         capture_output=True, text=True).stdout
        sub, repo = top / "sub", top / "app"
        for r in (sub, repo):
            g(top, "init", "-q", "-b", "main", r.name)
        (sub / "x.txt").write_text("x\n")
        g(sub, "add", "x.txt")
        g(sub, "commit", "-qm", "s1")
        (repo / "a.txt").write_text("a\n")
        g(repo, "add", "a.txt")
        g(repo, "-c", "protocol.file.allow=always", "submodule", "add", "-q", str(sub), "lib")
        g(repo, "commit", "-qm", "base")
        g(repo, "switch", "-qc", "delegate/t")
        (repo / "b.txt").write_text("b\n")
        g(repo, "add", "b.txt")
        g(repo, "commit", "-qm", "task")
        g(repo, "switch", "-q", "main")
        (repo / "c.txt").write_text("c\n")
        g(repo, "add", "c.txt")
        g(repo, "commit", "-qm", "main")
        return repo, lambda *a: g(repo, *a)

    def test_a_submodule_moved_or_edited_in_the_checkout_does_not_stop_the_merge(self):
        # #505 (Claude's audit of 1.90, reproduced): lib one commit ahead of its gitlink (a git
        # pull without submodule update) or edited inside: "app has uncommitted changes", naming
        # no file, where `git merge --no-ff` in the same state succeeds
        for state in ("moved", "edited"):
            repo, g = self._submodule_case()
            lib = repo / "lib"
            if state == "moved":
                (lib / "y.txt").write_text("y\n")
                g("-C", "lib", "add", "y.txt")
                g("-C", "lib", "commit", "-qm", "s2")
            else:
                (lib / "x.txt").write_text("edited\n")
            at = g("-C", "lib", "rev-parse", "HEAD")
            gitops.merge(repo, "t", "main")
            self.assertEqual((repo / "b.txt").read_text(), "b\n", state)
            self.assertEqual(g("-C", "lib", "rev-parse", "HEAD"), at, state)  # left as it was
            if state == "edited":
                self.assertEqual((lib / "x.txt").read_text(), "edited\n")

    def test_the_merge_refuses_naming_what_is_uncommitted_and_a_moved_submodule_it_would_change(self):
        # #505: a moved submodule whose gitlink the merge changes is in the way (named), and
        # uncommitted changes are named too
        repo, g = self._submodule_case()
        g("switch", "-q", "delegate/t")
        g("-C", "lib", "commit", "-q", "--allow-empty", "-m", "the task's")
        g("add", "lib")
        g("commit", "-qm", "the task moves lib")
        g("switch", "-q", "main")  # lib stays at the task's commit: moved, here
        g("-C", "lib", "commit", "-q", "--allow-empty", "-m", "mine")
        head = g("rev-parse", "HEAD")
        with self.assertRaisesRegex(gitops.GitError, "submodule lib is at another commit"):
            gitops.merge(repo, "t", "main")
        self.assertEqual(g("rev-parse", "HEAD"), head)
        g("add", "lib")  # staged: an uncommitted change of the checkout's own
        (repo / "a.txt").write_text("mine\n")
        with self.assertRaisesRegex(gitops.GitError, r"uncommitted changes \(a\.txt, lib\)"):
            gitops.merge(repo, "t", "main")

    def test_a_fast_forward_under_a_squash_merge_option_lands_or_is_backed_out_for_real(self):
        # #430 (the audit of 1.8, reproduced): with branch.main.mergeOptions=--squash, --ff-only
        # staged a squash and left HEAD; no MERGE_HEAD, so nothing was reset, and the checkout
        # kept `A b.txt` while wb said "it was backed out"
        repo, g = self._merge_case(base={b"a.txt": b"a\n"}, main={b"c.txt": b"c\n"},
                                   task={b"b.txt": b"b\n"}, ignore={},
                                   config=[("branch.main.mergeOptions", "--squash")])
        tip = g("rev-parse", "delegate/t").strip().decode()
        g("reset", "-q", "--hard", "HEAD~1")  # main at the base: it can fast-forward
        self.assertTrue(tip.startswith(gitops.merge(repo, "t", "main", how="ff")))
        self.assertEqual(g("rev-parse", "HEAD").strip().decode(), tip)
        self.assertEqual(g("status", "--porcelain"), b"")
        # a git that stages without moving HEAD and says nothing (--no-squash not honoured): what
        # wb says was backed out is
        g("reset", "-q", "--hard", "HEAD~1")
        real = gitops._run

        def squashing(cwd, args, *rest, **kw):
            return real(cwd, [x for x in args if x != "--no-squash"], *rest, **kw)
        with mock.patch.object(gitops, "_run", squashing), \
                self.assertRaisesRegex(gitops.GitError, "backed out"):
            gitops.merge(repo, "t", "main", how="ff")
        self.assertEqual(g("rev-parse", "HEAD"), g("rev-parse", f"{tip}~1"))
        self.assertEqual(g("status", "--porcelain"), b"")

    def _signer(self, hang_on_merge: bool = False) -> Path:
        """A gpg.program that signs unattended with a made-up signature (git checks only the
        status line), or, `hang_on_merge`, waits on nobody for a commit with two parents: a
        pinentry no one answers."""
        prog = Path(self.tmp.name) / f"signer{len(os.listdir(self.tmp.name))}"
        prog.write_text("#!/bin/sh\npayload=$(cat)\n" + (
            "if [ \"$(printf '%s\\n' \"$payload\" | grep -c '^parent ')\" -ge 2 ]; then exec sleep 30; fi\n"
            if hang_on_merge else "") +
            "printf '\\n[GNUPG:] SIG_CREATED D 22 8 00 0 FAKE\\n' >&2\n"
            "printf -- '-----BEGIN PGP SIGNATURE-----\\n\\nmade up\\n-----END PGP SIGNATURE-----\\n'\n")
        prog.chmod(0o755)
        return prog

    def test_a_signed_merge_no_one_answers_is_backed_out_in_time_and_no_sign_merges_unsigned(self):
        # #420 (the audit of 1.8, reproduced): the merge and the squash's commit in the user's
        # checkout ran with a terminal and no time limit, and signed after --no-sign
        slow = Path(self.tmp.name) / "slowgpg"
        slow.write_text("#!/bin/sh\nexec sleep 30\n")  # git is killed; this one lapses
        slow.chmod(0o755)
        for how in ("merge", "squash"):
            repo, g = self._merge_case(base={b"a.txt": b"a\n"}, main={b"c.txt": b"c\n"},
                                       task={b"b.txt": b"b\n"}, ignore={})
            g("config", "commit.gpgsign", "true")
            g("config", "gpg.program", str(slow))
            before = g("rev-parse", "main")
            t0 = time.monotonic()
            # SIGN_SECS too: the refusal asks this gpg whether the key is on a card, and waited
            # out its 10 s each time (2026-11-21)
            with mock.patch.object(gitops, "COMMIT_SECS", 2), mock.patch.object(gitops, "SIGN_SECS", 1), \
                    self.assertRaisesRegex(gitops.GitError, "backed out") as e:
                gitops.merge(repo, "t", "main", how=how)
            self.assertLess(time.monotonic() - t0, 20, how)
            self.assertIn("needs unlocking", str(e.exception), how)
            self.assertEqual(g("rev-parse", "main"), before, how)
            self.assertEqual(g("status", "--porcelain"), b"", how)  # nothing staged, no b.txt
            self.assertNotEqual(subprocess.run(["git", "-C", str(repo), "rev-parse", "-q", "--verify",
                                                "MERGE_HEAD"]).returncode, 0, how)
            head = gitops.merge(repo, "t", "main", how=how, sign=False)
            self.assertNotIn(b"gpgsig", g("cat-file", "commit", head), how)

    @unittest.skipUnless(shutil.which("timeout"), "needs timeout")
    def test_an_accept_merge_killed_mid_merge_leaves_the_checkout_as_it_was(self):
        # #420: under `timeout 4 wb accept --merge`, a signing key waiting on a pinentry left
        # MERGE_HEAD and the staged merge in the user's checkout, and the retry refused it
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True, text=True).stdout
        g("config", "commit.gpgsign", "true")
        g("config", "gpg.program", str(self._signer(hang_on_merge=True)))
        out = self.start("t-kill", "ok")
        self.assertNotIn("needs unlocking", out)                       # the signer works
        wait_phase("t-kill", {"review"})
        before = g("rev-parse", "main")
        r = subprocess.run(["timeout", "5", sys.executable, str(ROOT / "bin" / "wb"), "accept",
                            "t-kill", "-m", "feat: answer", "--merge"], capture_output=True, text=True)
        self.assertEqual(r.returncode, 124, r.stderr)                  # killed in the merge
        self.assertEqual(g("rev-parse", "main"), before)
        self.assertEqual(g("status", "--porcelain", "--untracked-files=no"), "")
        self.assertFalse((self.repo / "answer.txt").exists())
        self.assertNotEqual(subprocess.run(["git", "-C", str(self.repo), "rev-parse", "-q",
                                            "--verify", "MERGE_HEAD"]).returncode, 0)
        self.assertIn("gpgsig", g("cat-file", "commit", store.Task("t-kill").status["tip"]))
        self.assertIn("merged into main", run_wb("accept", "t-kill", "-m", "feat: answer",
                                                 "--merge", "--no-sign"))  # the retry lands it
        self.assertNotIn("gpgsig", g("cat-file", "commit", "main"))
        self.assertEqual((self.repo / "answer.txt").read_text().strip(), "42")

    def test_accept_merge_no_sign_merges_unsigned_when_the_key_cannot_sign(self):
        # #420 (Codex's 20 too): --no-sign let the task's commit through, then the merge signed,
        # failed ("gpg failed to sign the data") and exited 5: the task couldn't land
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True,  # noqa
                                      capture_output=True, text=True).stdout
        g("config", "commit.gpgsign", "true")
        g("config", "gpg.program", "false")
        for name, how in (("t-ns", ()), ("t-nsq", ("--merge-as", "squash"))):
            self.start(name, "ok", "--no-sign")
            wait_phase(name, {"review"})
