def write_skill(path: Path, name: str, description: str, body: str = "Do it this way.\n") -> Path:
    path.mkdir(parents=True, exist_ok=True)
    (path / "SKILL.md").write_text(f"---\nname: {name}\ndescription: {description}\n---\n{body}")
    return path


class SkillLibrary(Base):
    """Claude's skills for the agents: written and checked, handed to one task, taken back, judged."""

    def draft(self, name, description="Use when drawing bar charts as SVG.", body="Steps.\n"):
        return write_skill(Path(self.tmp.name) / "drafts" / name, name, description, body)

    def test_add_checks_the_skill_and_keeps_its_history(self):
        from workbench import skills
        self.assertIn("added svg-charts", run_wb("skill", "add", "svg-charts", "--from",
                                                 str(self.draft("svg-charts")), "-m", "axis labels"))
        self.assertIn("updated svg-charts", run_wb("skill", "add", "svg-charts", "--from", str(
            self.draft("svg-charts", body="Better steps.\n") / "SKILL.md"), "-m", "clearer"))
        self.assertIn("Better steps.", run_wb("skill", "show", "svg-charts"))
        self.assertEqual(len(skills.history("svg-charts")), 2)            # why each change was made
        for why, make in (("directory is 'x'", lambda: self.draft("other-name") / "SKILL.md"),
                          ("chars (max", lambda: self.draft("x", "Use when " + "very " * 80)),
                          ("bytes (max", lambda: self.draft("x", body="y" * 9000))):
            err = io.StringIO()
            with self.assertRaises(SystemExit), redirect_stderr(err):
                run_wb("skill", "add", "x", "--from", str(make()), "-m", "no")
            self.assertIn(why, err.getvalue())
        out = run_wb("skill", "add", "paths", "--from", str(self.draft(
            "paths", "Draws things.", "Read ~/notes/plan.md first.\n")), "-m", "warned")
        self.assertIn("outside the repo", out)
        self.assertIn("when to use it", out)
        for path in ("/Users/alice/proj/tools.py", "/var/home/alice/x", "/root/x"):  # not only Linux's
            out = run_wb("skill", "add", "paths", "--from", str(self.draft(
                "paths", "Use when drawing.", f"Read {path} first.\n")), "-m", "warned")
            self.assertIn("outside the repo", out, path)

    def test_two_skill_changes_at_once_each_commit_only_their_own_skill(self):
        # #822: B's `git add` landed between A's add and its path-less commit, so A committed both
        # under its message and B's own message, source and review record never reached the history
        from workbench import skills
        run_wb("skill", "add", "first", "--from", str(self.draft("first")), "-m", "the library")
        lib = skills.library()
        write_skill(lib / "b-skill", "b-skill", "Use when B.")             # B, between add and commit
        skills._git("add", "-A", "--", "b-skill")
        run_wb("skill", "add", "a-skill", "--from", str(self.draft("a-skill")), "-m", "A's reason")
        self.assertEqual(skills._git("show", "--name-only", "--format=", "HEAD").split(),
                         ["a-skill/SKILL.md"])
        run_wb("skill", "add", "b-skill", "--from", str(self.draft("b-skill", "Use when B.")), "-m", "B's reason")
        self.assertEqual(skills.history("b-skill")[0].split(" ", 1)[1], "b-skill: B's reason")
        run_wb("skill", "retire", "a-skill", "-m", "done")
        self.assertEqual(sorted(skills._git("show", "--no-renames", "--name-only", "--format=", "HEAD").split()),
                         ["a-skill/SKILL.md", "retired/a-skill/SKILL.md"])

    def test_a_skill_change_waits_for_the_library_lock_and_a_failed_commit_leaves_nothing_live(self):
        # #822: unlocked, overlapping git calls met each other's index.lock, and one skill was left
        # in place but uncommitted, live with the previous version's rev
        from workbench import skills
        lock = store.home() / "locks" / "skills.lock"
        lock.parent.mkdir(parents=True, exist_ok=True)
        held = subprocess.Popen([sys.executable, "-c", (
            "import fcntl, sys, time\nf = open(sys.argv[1], 'a+')\nfcntl.flock(f, fcntl.LOCK_EX)\n"
            "print('held', flush=True)\ntime.sleep(1.5)"), str(lock)], stdout=subprocess.PIPE, text=True)
        self.assertEqual(held.stdout.readline().strip(), "held")
        began = time.monotonic()
        skills.add(self.draft("waited"), "waited", "after the other")
        self.assertGreater(time.monotonic() - began, 1.0)                    # it waited its turn
        held.wait()
        rev = skills.rev("waited")
        with mock.patch.object(skills, "_commit", side_effect=RuntimeError(
                "Unable to create '.git/index.lock': File exists")):
            with self.assertRaises(RuntimeError):
                skills.add(self.draft("fresh"), "fresh", "new")
            with self.assertRaises(RuntimeError):
                skills.add(self.draft("waited", body="Changed.\n"), "waited", "an update")
        self.assertNotIn("fresh", skills.available())                       # not live, uncommitted
        self.assertFalse((skills.library() / "fresh").exists())
        self.assertEqual((skills.library() / "waited" / "SKILL.md").read_text(),
                         (self.draft("waited") / "SKILL.md").read_text())    # the committed copy
        self.assertEqual((skills.rev("waited"), skills._git("status", "--porcelain").strip()), (rev, ""))

    def test_a_skill_md_opening_with_a_utf8_bom_is_read_and_kept_without_it(self):
        # #479 (the audit of 1.8, reproduced): a Windows editor's BOM before the `---` hid the
        # front matter: "front matter name is ''", "no description"
        from workbench import skills
        d = self.draft("bom-skill")
        md = d / "SKILL.md"
        md.write_bytes(b"\xef\xbb\xbf" + md.read_bytes().replace(b"\n", b"\r\n"))
        self.assertIn("added bom-skill", run_wb("skill", "add", "bom-skill", "--from", str(d),
                                                "-m", "from Windows"))
        self.assertEqual(skills.available()["bom-skill"]["description"],
                         "Use when drawing bar charts as SVG.")
        self.assertFalse((skills.library() / "bom-skill" / "SKILL.md").read_bytes()
                         .startswith(b"\xef\xbb\xbf"))  # what OpenCode reads opens with `---`

    def test_a_skill_with_a_dangling_or_looping_link_is_refused_and_the_old_copy_stays(self):
        # #604 (Claude's audit of 1.90, reproduced): notes.md -> missing.md was only a high
        # finding and `self -> .` none, so the copy began, failed partway, and left the skill
        # live but uncommitted; retire then raised "source directory is empty"
        from workbench import skills
        run_wb("skill", "add", "demo", "--from", str(self.draft("demo")), "-m", "first")
        before = (skills.library() / "demo" / "SKILL.md").read_text()
        for link, to in (("notes.md", "missing.md"), ("self", "."), ("up", "..")):
            d = self.draft("demo", body="Changed.\n")
            for old in ("notes.md", "self", "up"):
                (d / old).unlink(missing_ok=True)
            (d / link).symlink_to(to)
            err = io.StringIO()
            with self.assertRaises(SystemExit), redirect_stderr(err):
                run_wb("skill", "add", "demo", "--from", str(d), "-m", "broken")
            self.assertIn("not added: scan: ", err.getvalue())
            self.assertEqual((skills.library() / "demo" / "SKILL.md").read_text(), before, link)
            self.assertEqual(skills._git("status", "--porcelain"), "")
        # a copy that fails all the same (a file it can't read) leaves the old copy too
        d = self.draft("demo", body="Changed.\n")
        for old in ("notes.md", "self", "up"):
            (d / old).unlink(missing_ok=True)
        (d / "z.md").write_text("more\n")
        real = shutil.copytree

        def copy(a, b, **k):  # SKILL.md copied, then z.md refused: half a skill
            if Path(a).name == "z.md":
                raise PermissionError(13, "Permission denied", a)
            return shutil.copy2(a, b, **k)
        err = io.StringIO()
        with (mock.patch("shutil.copytree", lambda a, b, **k: real(a, b, copy_function=copy, **k)),
              self.assertRaises(SystemExit), redirect_stderr(err)):
            run_wb("skill", "add", "demo", "--from", str(d), "-m", "unreadable")
        self.assertRegex(err.getvalue(), r"not added: couldn't copy .*z.md: .*Permission denied")
        self.assertEqual((skills.library() / "demo" / "SKILL.md").read_text(), before)
        self.assertEqual(skills._git("status", "--porcelain"), "")
        self.assertEqual(list(skills.available()), ["demo"])
        run_wb("skill", "retire", "demo", "-m", "done")      # and it retires as it was

    def test_the_librarys_commits_ignore_the_users_signing_and_hooks(self):
        # a signing prompt or a global hook failed `wb skill add` from Claude's Bash (the 2026-11-16 audit)
        hooks = Path(self.tmp.name) / "hooks"
        hooks.mkdir()
        (hooks / "pre-commit").write_text("#!/bin/sh\nexit 1\n")
        (hooks / "pre-commit").chmod(0o755)
        conf = Path(self.tmp.name) / "gitconfig"
        conf.write_text(f"[commit]\n\tgpgsign = true\n[gpg]\n\tprogram = false\n[core]\n\thooksPath = {hooks}\n")
        os.environ["GIT_CONFIG_GLOBAL"] = str(conf)
        self.assertIn("added svg-charts", run_wb("skill", "add", "svg-charts", "--from",
                                                 str(self.draft("svg-charts")), "-m", "signed nowhere"))

    def test_the_library_is_made_on_a_git_without_init_b_and_doctor_names_a_git_below_the_floor(self):
        # #527 (the audit of v1.90): git before 2.28 refused `init -b`, the library was never
        # made and `wb skill add` ended in a traceback; wb doctor accepted any git
        shim = Path(self.tmp.name) / "old-git"
        shim.mkdir()
        real = shutil.which("git")
        (shim / "git").write_text(
            '#!/bin/sh\nfor a in "$@"; do [ "$a" = -b ] && [ "$prev" = -q ] && [ "$init" ] && '
            '{ echo "error: unknown switch b" >&2; exit 129; }; [ "$a" = init ] && init=1; '
            'prev=$a; done\n'
            f'[ "$1" = --version ] && {{ echo "git version 2.25.1"; exit 0; }}\nexec {real} "$@"\n')
        (shim / "git").chmod(0o755)
        lib = Path(os.environ["WB_SKILLS"])
        with mock.patch.dict(os.environ, PATH=f"{shim}:{os.environ['PATH']}"):
            self.assertNotEqual(subprocess.run(["git", "init", "-q", "-b", "x", str(lib) + "-x"],
                                               capture_output=True).returncode, 0)  # the shim bites
            self.assertIn("added svg-charts", run_wb("skill", "add", "svg-charts", "--from",
                                                     str(self.draft("svg-charts")), "-m", "old git"))
            gitops.version.cache_clear()
            try:
                buf = io.StringIO()
                with redirect_stdout(buf):
                    try:
                        cli.main(["doctor"])
                    except SystemExit:
                        pass
            finally:
                gitops.version.cache_clear()
        self.assertEqual(subprocess.run(["git", "-C", str(lib), "symbolic-ref", "HEAD"], text=True,
                                        capture_output=True).stdout.strip(), "refs/heads/master")
        self.assertIn("BAD git version 2.25.1: workbench needs git 2.34 or newer", buf.getvalue())

    def test_a_library_skill_a_personal_one_later_shadows_is_still_handed_and_listed_as_such(self):
        # #515 (the audit of v1.90): the app synced a personal `pdf` after the library had one,
        # and the handed skill was denied by name to every agent it went to
        home = Path(self.tmp.name) / "home"
        home.mkdir()
        with mock.patch.dict(os.environ, {"HOME": str(home)}):
            run_wb("skill", "add", "pdf", "--from", str(self.draft("pdf", "Use when reading PDFs.")),
                   "-m", "first")
            write_skill(home / ".claude" / "skills" / "synced" / "org" / "pdf", "pdf", "Use when PDF.")
            write_skill(home / ".claude" / "skills" / "mine", "mine", "Use when mine.")
            self.start("t-pdf", "ok", "--skill", "pdf")
            wait_phase("t-pdf", {"review"})
            layer = context.layer(store.Task("t-pdf"))
            listed = run_wb("skill", "list")
        denied = {r["resource"] for r in layer["permissions"] if r["action"] == "skill"}
        self.assertNotIn("pdf", denied)
        self.assertTrue({"mine", "workbench"} <= denied)
        self.assertEqual(layer["skills"], [str(Path(os.environ["WB_SKILLS"]) / "pdf")])
        self.assertIn("one of the user's own skills has this name too", listed)

    def test_the_users_own_skill_names_are_off_limits(self):
        home = Path(self.tmp.name) / "home"
        write_skill(home / ".claude" / "skills" / "publishing-arm", "publishing-arm", "Use when publishing.")
        os.environ["HOME"] = str(home)
        with self.assertRaises(SystemExit):
            run_wb("skill", "add", "publishing-arm", "--from", str(self.draft("publishing-arm")), "-m", "no")

    def test_retired_skills_leave_the_library_and_can_come_back(self):
        run_wb("skill", "add", "old", "--from", str(self.draft("old")), "-m", "first")
        run_wb("skill", "retire", "old", "-m", "the model learned it")
        self.assertIn("empty", run_wb("skill", "list"))
        with self.assertRaises(SystemExit):
            self.start("t-old", "ok", "--skill", "old")                  # not in the library now
        run_wb("skill", "restore", "old")
        self.assertIn("old:", run_wb("skill", "list"))

    def test_a_handed_skill_reaches_only_its_task_and_can_be_taken_back(self):
        run_wb("skill", "add", "alpha", "--from", str(self.draft("alpha", "Use when ALPHA.")), "-m", "a")
        run_wb("skill", "add", "beta", "--from", str(self.draft("beta", "Use when BETA.")), "-m", "b")
        prompts = Path(self.tmp.name) / "prompts.jsonl"
        os.environ["FAKE_PROMPTS"] = str(prompts)
        self.assertIn("skills handed: alpha", self.start("t-sk", "fix", "--auto-fix", "0", "--skill", "alpha"))
        wait_phase("t-sk", {"review"})
        task = store.Task("t-sk")
        layer = json.loads((context.rules_dir(task) / "opencode.json").read_text())
        self.assertEqual(layer["skills"], [str(Path(os.environ["WB_SKILLS"]) / "alpha")])  # not beta
        first = json.loads(prompts.read_text().splitlines()[0])
        self.assertIn("Claude picked these skills", first)
        self.assertIn("`alpha`: Use when ALPHA.", first)
        self.assertNotIn("BETA", first)
        self.assertIn("holds: alpha, beta", run_wb("skill", "hand", "t-sk", "beta"))
        run_wb("skill", "take", "t-sk", "alpha")
        run_wb("feedback", "t-sk", "--text", "1. The answer is 42.")
        wait_phase("t-sk", {"review"})
        layer = json.loads((context.rules_dir(task) / "opencode.json").read_text())
        self.assertEqual(layer["skills"], [str(Path(os.environ["WB_SKILLS"]) / "beta")])
        second = json.loads(prompts.read_text().splitlines()[1])
        self.assertIn("`beta`: Use when BETA.", second)                  # only what changed
        self.assertIn("Claude took back: `alpha`", second)
        self.assertNotIn("ALPHA.", second)
        self.assertIn("Claude → agent · skills", "\n".join(
            t for e in transcript.task_entries(task) for _, t in e.lines))
        run_wb("accept", "t-sk", "-m", "feat: answer")
        row = store.read_jsonl(store.home() / "results.jsonl")[0][-1]
        self.assertEqual(row["skills_offered"], ["alpha", "beta"])

    def test_a_fresh_session_hears_the_skills_again(self):
        from workbench import runner as r
        run_wb("skill", "add", "alpha", "--from", str(self.draft("alpha", "Use when ALPHA.")), "-m", "a")
        self.start("t-fr", "ok", "--skill", "alpha")
        wait_phase("t-fr", {"review"})
        task = store.Task("t-fr")
        self.assertEqual(r.skills_note(task, 2), "")                     # told already, nothing new
        task.set_status(skills_told=None)                                # what _start_fresh does
        self.assertIn("`alpha`", r.skills_note(task, 2))

    def test_the_record_says_which_skills_earn_their_place(self):
        from workbench import skills
        row = events.normalize({"type": "tool_use", "part": {"tool": "skill", "state": {
            "status": "completed", "input": {"id": "alpha"}}}}, 1)
        self.assertEqual(row["brief"], "alpha")                           # loads are recorded by name
        now = store.now()
        for loaded, outcome in ((["alpha"], "accepted"), ([], "accepted"), ([], "discarded")):
            store.append_jsonl(store.home() / "results.jsonl", {
                "ts": now, "outcome": outcome, "skills_offered": ["alpha", "beta"],
                "skills_loaded": loaded})
        use = skills.usage()
        self.assertEqual({k: use["alpha"][k] for k in ("offered", "loaded", "accepted", "last")},
                         {"offered": 3, "loaded": 1, "accepted": 1, "last": now})
        self.assertIn("never loaded", skills.advice(use["beta"], now))
        self.assertEqual(skills.advice(use["alpha"], now), "")
        self.assertIn("60 days", skills.advice(use["alpha"], now + 61 * 86400))


@unittest.skipUnless(shutil.which("opencode"), "needs the real opencode")
class RealOpenCode(Base):
    """Guards the OpenCode behaviour context.py relies on, with a model server that records."""

    def test_what_the_model_receives(self):
        from workbench import runner
        (self.repo / "CLAUDE.md").write_text("CANARY-CLAUDE-MD: follow me\n")
        subprocess.run(["git", "-C", str(self.repo), "add", "CLAUDE.md"], check=True)
        subprocess.run(["git", "-C", str(self.repo), "commit", "-qm", "rules"], check=True)
        lib = Path(os.environ["WB_SKILLS"])
        write_skill(lib / "handed", "handed", "Use when CANARY-HANDED.")
        write_skill(lib / "kept", "kept", "Use when CANARY-KEPT.")       # in the library, not handed
        self.start("t-real", "ok", "--skill", "handed")
        wait_phase("t-real", {"review"})
        task = store.Task("t-real")
        with socket.socket() as sock:
            sock.bind(("127.0.0.1", 0))
            port = sock.getsockname()[1]
        out = Path(self.tmp.name) / "requests.jsonl"
        server = subprocess.Popen([sys.executable, str(ROOT / "tests" / "capture_llm.py"),
                                   str(port), str(out)])
        self.addCleanup(server.kill)
        layer_path = runner.write_config_layer(task)
        layer = json.loads(layer_path.read_text())
        layer["provider"] = {"cap": {
            "npm": "@ai-sdk/openai-compatible",
            "options": {"baseURL": f"http://127.0.0.1:{port}/v1", "apiKey": "x"},
            "models": {"cap": {"name": "capture", "tool_call": True,
                               "limit": {"context": 32768, "output": 1024}}}}}
        layer_path.write_text(json.dumps(layer))
        time.sleep(0.5)
        listed = ask_mcp.ask_dir(task) / ask_mcp.LISTED
        listed.unlink(missing_ok=True)                   # the fake's run listed it too
        env = {**os.environ, **context.opencode_home_env(task), "PWD": str(task.worktree),
               "OPENCODE_CONFIG": str(layer_path)}             # the task's store, not the user's
        subprocess.run(["opencode", "run", "--standalone", "-m", "cap/cap", "--format", "json",
                        "say ok"], cwd=task.worktree, env=env, capture_output=True, timeout=120)
        reqs = [json.loads(line) for line in out.read_text().splitlines()]
        agent = max(reqs, key=lambda r: len(r.get("tools", [])))  # not the title request
        text = json.dumps(agent["messages"])
        tools = {t["function"]["name"] for t in agent["tools"]}
        self.assertTrue(listed.exists())                 # the round report's check (finding 26)
        # OpenCode's own share of the fixed prompt, as wb start estimates it (finding 27)
        ours = sum(len(Path(f).read_text()) for f in json.loads(layer_path.read_text())["instructions"])
        own = (len(text) + len(json.dumps(agent["tools"])) - ours) // context.CHARS_PER_TOKEN
        self.assertLess(abs(own - context.OPENCODE_BASE_TOKENS), context.OPENCODE_BASE_TOKENS / 2, own)
        self.assertIn("CANARY-CLAUDE-MD", text)          # CLAUDE.md reaches the model
        self.assertIn("Workbench handbook", text)
        self.assertIn("workbench_ask_reviewer", tools)
        self.assertTrue({"edit", "read", "shell"} <= tools)
        self.assertFalse({"question", "execute", "subagent"} & tools)
        self.assertNotIn("<id>workbench</id>", text)
        self.assertIn("CANARY-HANDED", text)              # a handed skill is listed to the model
        self.assertNotIn("CANARY-KEPT", text)             # and the rest of the library is not

    @home_outside_the_lane
    def test_claude_md_imports_reach_the_model_in_the_lane_and_secrets_stay_out(self):
        # #513 (the audit of 1.90): OpenCode reads an instruction file as a raw string, so
        # `See @docs/testing.md` reached the agent as that line, and an import into ~/.claude
        # was unreadable in the lane. The user's own file is ~/.config/workbench/AGENTS.md, and
        # Claude's CLAUDE.md and rules reach no agent (#1061)
        from workbench import runner
        home = Path(tempfile.mkdtemp(dir=Path.home(), prefix=".wb-imports-test-"))  # outside a temp root
        self.addCleanup(shutil.rmtree, home, True)
        os.environ["HOME"] = str(home)
        for v in ("CLAUDE_CONFIG_DIR", "XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_STATE_HOME"):
            os.environ.pop(v, None)
        claude, config = home / ".claude", home / ".config" / "workbench"   # both hidden from the lane
        (claude / "rules").mkdir(parents=True)
        config.mkdir(parents=True)
        (claude / "CLAUDE.md").write_text("CANARY-CLAUDE-GLOBAL @rules/python.md\n")
        (claude / "rules" / "python.md").write_text("CANARY-CLAUDE-IMPORT\n")
        (claude / "rules" / "style.md").write_text("CANARY-CLAUDE-RULE\n")
        (config / "AGENTS.md").write_text("CANARY-AGENTS-MD, then @python.md\n")
        (config / "python.md").write_text("CANARY-USER-IMPORT\n")
        (claude / "notes.md").write_text("CANARY-CLAUDE-NOTES\n")
        (claude / ".credentials.json").write_text("CANARY-CREDENTIAL\n")
        outside = Path(self.tmp.name) / "elsewhere.md"
        outside.write_text("CANARY-OUTSIDE\n")
        (self.repo / "docs").mkdir()
        for name, text in (("testing", "CANARY-IMPORTED, then @deeper.md"), ("deeper", "CANARY-DEEPER"),
                           ("span", "CANARY-SPAN"), ("fenced", "CANARY-FENCED")):
            (self.repo / "docs" / f"{name}.md").write_text(text + "\n")
        (self.repo / "CLAUDE.md").write_text(
            "See @docs/testing.md and @docs/missing.md, not `see @docs/span.md first`.\n"
            "```\n@docs/fenced.md\n```\n<!-- @docs/span.md -->\n"
            f"@{claude}/notes.md @{claude}/.credentials.json @{outside}\n")
        subprocess.run(["git", "-C", str(self.repo), "add", "."], check=True)
        subprocess.run(["git", "-C", str(self.repo), "commit", "-qm", "imports"], check=True)
        self.start("t-imp", "ok")
        wait_phase("t-imp", {"review"})
        task = store.Task("t-imp")
        files, _ = context.instruction_files(task)
        rules = context.rules_dir(task)
        self.assertEqual([p for p in files if p.name in ("testing.md", "deeper.md")],
                         [task.worktree / "docs" / "testing.md", task.worktree / "docs" / "deeper.md"])
        self.assertTrue(all(p.is_relative_to(rules) for p in files if p.name in ("python.md", "notes.md")))
        self.assertIn("docs/testing.md", dict(context.fixed_prompt(task)[1]))  # counted at wb start
        with socket.socket() as sock:
            sock.bind(("127.0.0.1", 0))
            port = sock.getsockname()[1]
        out = Path(self.tmp.name) / "imports-requests.jsonl"
        server = subprocess.Popen([sys.executable, str(ROOT / "tests" / "capture_llm.py"),
                                   str(port), str(out)])
        self.addCleanup(server.kill)
        env = runner.opencode_env(task)
        layer_path = Path(env["OPENCODE_CONFIG"])
        layer = json.loads(layer_path.read_text())
        layer["provider"] = {"cap": {
            "npm": "@ai-sdk/openai-compatible",
            "options": {"baseURL": f"http://127.0.0.1:{port}/v1", "apiKey": "x"},
            "models": {"cap": {"name": "capture", "tool_call": True,
                               "limit": {"context": 32768, "output": 1024}}}}}
        layer_path.write_text(json.dumps(layer))
        time.sleep(0.5)
        cmd = lane.wrap(context.writable(task), ["opencode", "run", "--standalone", "-m", "cap/cap",
                                                 "--format", "json", "say ok"],
                        context.readable(task), context.unix_paths(task))
        subprocess.run(cmd, cwd=task.worktree, env=env, capture_output=True, timeout=180)
        reqs = [json.loads(line) for line in out.read_text().splitlines()]
        text = json.dumps(max(reqs, key=lambda r: len(r.get("tools", [])))["messages"])
        for seen in ("CANARY-IMPORTED", "CANARY-DEEPER", "CANARY-AGENTS-MD", "CANARY-USER-IMPORT",
                     "CANARY-CLAUDE-NOTES"):
            self.assertIn(seen, text)
        for unseen in ("CANARY-SPAN", "CANARY-FENCED", "CANARY-CREDENTIAL", "CANARY-OUTSIDE",
                       "CANARY-CLAUDE-GLOBAL", "CANARY-CLAUDE-IMPORT", "CANARY-CLAUDE-RULE"):
            self.assertNotIn(unseen, text)

    def test_opencode_without_the_lane_reads_no_claude_md_of_the_users(self):
        # #1061 (2026-11-23): OpenCode 2.3 reads ~/.claude/CLAUDE.md itself as a global
        # instruction, which only the lane's SECRETS kept from the agent: with no Landlock
        # (macOS, an old kernel, "paths": ["*"]) the user's CLAUDE.md, written to Claude, reached
        # every agent. runner.OPENCODE_ENV's switch keeps it out; without it, it is read, so the
        # quirk the switch answers is still there
        from workbench import runner
        home = Path(self.tmp.name) / "home"
        (home / ".claude").mkdir(parents=True)
        (home / ".claude" / "CLAUDE.md").write_text("CANARY-CLAUDE-GLOBAL\n")
        os.environ["HOME"] = str(home)
        for v in ("CLAUDE_CONFIG_DIR", "XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_STATE_HOME"):
            os.environ.pop(v, None)
        self.start("t-nolane", "ok")
        wait_phase("t-nolane", {"review"})
        task = store.Task("t-nolane")
        with socket.socket() as sock:
            sock.bind(("127.0.0.1", 0))
            port = sock.getsockname()[1]
        out = Path(self.tmp.name) / "nolane-requests.jsonl"
        server = subprocess.Popen([sys.executable, str(ROOT / "tests" / "capture_llm.py"),
                                   str(port), str(out)])
        self.addCleanup(server.kill)
        env = runner.opencode_env(task)
        layer_path = Path(env["OPENCODE_CONFIG"])
        layer = json.loads(layer_path.read_text())
        layer["provider"] = {"cap": {
            "npm": "@ai-sdk/openai-compatible",
            "options": {"baseURL": f"http://127.0.0.1:{port}/v1", "apiKey": "x"},
            "models": {"cap": {"name": "capture", "tool_call": True,
                               "limit": {"context": 32768, "output": 1024}}}}}
        layer_path.write_text(json.dumps(layer))
        time.sleep(0.5)
        seen = []
        for switch in (True, False):
            run_env = {k: v for k, v in env.items()
                       if switch or k != "OPENCODE_DISABLE_CLAUDE_CODE_PROMPT"}
            out.unlink(missing_ok=True)
            subprocess.run(["opencode", "run", "--standalone", "-m", "cap/cap", "--format", "json",
                            "say ok"], cwd=task.worktree, env=run_env, capture_output=True, timeout=180)
            reqs = [json.loads(line) for line in out.read_text().splitlines()]
            seen.append("CANARY-CLAUDE-GLOBAL" in json.dumps(
                max(reqs, key=lambda r: len(r.get("tools", [])))["messages"]))
        self.assertEqual(seen, [False, True])

    def test_wb_reads_the_config_files_opencode_reads_under_opencode_config_dir(self):
        # #370 (the audit of 1.6): OpenCode 2.3 takes its global directory from
        # OPENCODE_CONFIG_DIR, and wb read ~/.config/opencode
        from workbench import models
        mine = Path(self.tmp.name) / "dotfiles"
        mine.mkdir()
        (mine / "opencode.json").write_text(json.dumps({"provider": {
            "ollama": OPENCODE_CONFIG["provider"]["ollama"]}}))
        (mine / "opencode.jsonc").write_text("{// a comment\n}")
        del os.environ["WB_OPENCODE_CONFIG"]
        os.environ.pop("OPENCODE_CONFIG", None)
        os.environ["OPENCODE_CONFIG_DIR"] = str(mine)
        empty = Path(tempfile.mkdtemp())    # no project config there or above (OpenCode looks up)
        self.addCleanup(shutil.rmtree, empty, True)
        out = subprocess.run(["opencode", "debug", "config", "--standalone"], cwd=empty,
                             env={**os.environ, "PWD": str(empty)}, capture_output=True, text=True,
                             timeout=60).stdout
        theirs = [Path(x["path"]) for x in json.loads(out[out.index("["):])
                  if x.get("type") == "document"]
        self.assertEqual(models.opencode_config_files(), theirs)
        self.assertIn("ollama/qwen3.8-27b", models.discover())

