class Try(Base):
    def test_wb_try_leaves_pythons_caches_in_the_clones_sample_behind(self):
        # 2026-11-21: a run of the sample's tests in place left __pycache__ in the clone's copy,
        # and wb init refused the sample as installed or generated files: wb try never started
        src = Path(self.tmp.name) / "try-src"
        shutil.copytree(cli.TRY, src)
        for d in (src / "project", src / "project" / "tests"):
            (d / "__pycache__").mkdir(exist_ok=True)
            (d / "__pycache__" / "x.cpython-311.pyc").write_bytes(b"\0")
        os.environ["FAKE_SCENARIO"] = "ok"
        with mock.patch.object(cli, "TRY", src):
            run_wb("try", "--model", "mimo")
        self.assertFalse(list((cli.try_dir() / "1").rglob("__pycache__")))
        wait_phase("try-1", {"review"})

    def test_wb_try_starts_the_sample_and_its_hidden_check_fails_until_median_is_written(self):
        # #112: a sample task that proves the setup, graded by a check the agent never sees
        os.environ["FAKE_SCENARIO"] = "ok"
        out = run_wb("try", "--model", "mimo")
        task = store.Task("try-1")
        self.assertTrue(task.spec["trial"])                               # never the evidence
        self.assertEqual(task.spec["size"], "trivial")
        # wb's own Python, not PATH's python3, which on RHEL 8 is 3.6 (#530)
        self.assertIn(f"hidden check, at review: {shlex.quote(sys.executable)} ", out)
        self.assertEqual(task.spec["test_cmd"], f"{shlex.quote(sys.executable)} -m unittest")
        check = shlex.split(out.split("hidden check, at review: ")[1].splitlines()[0])
        self.assertEqual(check[-1], str(task.worktree))
        wait_phase("try-1", {"review"})
        repo = cli.try_dir() / "1"
        self.assertFalse(any(os.path.realpath(repo).startswith(p + os.sep)
                             for p in context.private_paths()))            # the lane shows it (#164)
        seen = context.readable(task)
        if seen is not None:                                              # Landlock here: its git dir
            git_dir = os.path.realpath(repo / ".git")
            self.assertTrue(any(git_dir == os.path.realpath(p) or git_dir.startswith(os.path.realpath(p) + os.sep)
                                for p in seen))
        self.assertTrue((repo / "CLAUDE.md").exists())
        self.assertEqual(gitops.git(repo, "status", "--porcelain").strip(), "")   # wb init committed it
        base = subprocess.run(check[:-1] + [str(repo)], capture_output=True, text=True)
        self.assertEqual(base.returncode, 1, base.stdout)                 # fails on the untouched base
        self.assertIn("no stats.median", base.stdout + base.stderr)
        with open(task.worktree / "stats.py", "a") as fh:                 # what the spec asks
            fh.write("\n\ndef median(xs: list[float]) -> float:\n    \"\"\"The middle value of xs.\"\"\"\n"
                     "    if not xs:\n        raise ValueError(\"median of no values\")\n"
                     "    s, n = sorted(xs), len(xs)\n"
                     "    return s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) / 2\n")
        done = subprocess.run(check, capture_output=True, text=True)
        self.assertEqual(done.returncode, 0, done.stdout)
        self.assertIn("hidden check: PASS", done.stdout)
        self.assertFalse((task.worktree / "__pycache__").exists())        # it leaves no trace
        run_wb("discard", "try-1")
        run_wb("try", "--model", "mimo")                                  # the next gets its own
        self.assertTrue(store.Task("try-2").exists and (cli.try_dir() / "2").is_dir())
        wait_phase("try-2", {"review"})
        run_wb("discard", "try-2")
        with self.assertRaises(SystemExit), redirect_stderr(io.StringIO()):
            run_wb("try", "--model", "no-such-model")                     # refused: nothing left
        self.assertFalse((cli.try_dir() / "3").exists())          # (#161)

    def test_wb_try_refused_by_wb_init_leaves_no_sample_behind(self):
        # #530: with no git identity wb init refused, and try/1, try/2… were left at each retry.
        # useConfigOnly: git makes no identity up from the user and host names, as it does on a
        # Mac (user@host.local), where a host name without a domain makes none (#950)
        noid = Path(self.tmp.name) / "no-identity.gitconfig"
        noid.write_text("[user]\n\tuseConfigOnly = true\n")
        os.environ.update(GIT_CONFIG_GLOBAL=str(noid), GIT_CONFIG_NOSYSTEM="1")
        for k in ("GIT_AUTHOR_NAME", "GIT_AUTHOR_EMAIL", "GIT_COMMITTER_NAME", "GIT_COMMITTER_EMAIL",
                  "EMAIL"):
            os.environ.pop(k, None)
        for _ in range(2):
            with self.assertRaises(SystemExit), redirect_stderr(io.StringIO()) as err:
                run_wb("try", "--model", "mimo")
            self.assertIn("no user.name/user.email", err.getvalue())
        self.assertEqual(list(cli.try_dir().glob("*")) if cli.try_dir().exists() else [], [])

    def test_the_hidden_check_reports_a_sample_its_python_cannot_read(self):
        # #530: it caught only ImportError, so a SyntaxError crashed it with a traceback
        work = Path(self.tmp.name) / "unreadable"
        work.mkdir()
        (work / "stats.py").write_text("def median(xs:\n")
        r = subprocess.run([sys.executable, str(cli.TRY / "check.py"), str(work)],
                           capture_output=True, text=True)
        self.assertEqual(r.returncode, 1)
        self.assertIn("hidden check: FAIL (no stats.median", r.stderr)
        self.assertNotIn("Traceback", r.stderr)


class Coding(Base):
    """When Claude may write code for a delegated task: the user's choice (#92)."""
    def refused(self, *argv) -> tuple[int, str]:
        err = io.StringIO()
        with self.assertRaises(SystemExit) as e, redirect_stderr(err):
            run_wb(*argv)
        return e.exception.code, err.getvalue()

    def test_without_a_saved_choice_claude_decides_as_before(self):
        self.assertIn("Claude coding: Let Claude decide.", run_wb("coding"))
        self.start("t", "ok")
        wait_phase("t", {"review"})
        self.assertIn("took over t", run_wb("takeover", "t"))

    def test_ask_me_first_takes_the_users_yes_for_that_task_until_it_goes_back_to_the_agent(self):
        self.assertIn("Ask me first. Claude can ask", run_wb("coding", "ask"))
        self.start("t", "ok")
        wait_phase("t", {"review"})
        code, err = self.refused("takeover", "t")
        self.assertEqual(code, 3)
        self.assertIn("ask the user, naming the exact edit", err)
        out = run_wb("coding", "allow", "t", "--edit", "divide the reading by 1000 in power.py",
                     "--said", "yes, fix it")
        self.assertIn("Claude may make this edit", out)
        self.assertIn('t: allowed until handed back: divide the reading by 1000 in power.py '
                      '(the user: "yes, fix it")', run_wb("coding"))
        self.assertIn("took over t", run_wb("takeover", "t"))
        os.environ["FAKE_SCENARIO"] = "ok"
        run_wb("feedback", "t", "--text", "tests next")              # handed back: spent
        wait_phase("t", {"review"})
        self.assertEqual(self.refused("takeover", "t")[0], 3)        # the next edit asks again
        rows = json.loads((store.Task("t").dir / "coding.json").read_text())["allowed"]
        self.assertTrue(rows[0]["used"])                             # a retry remembers it

    def test_a_one_task_exception_waits_for_its_condition_and_is_spent_once_used(self):
        # #94: "if the next try still gets the units wrong, Claude may fix the conversion once"
        run_wb("coding", "only")
        self.start("t", "ok")
        wait_phase("t", {"review"})
        out = run_wb("coding", "allow", "t", "--edit", "divide by 1000 in power.py", "--said", "ok",
                     "--when", "the next try still shows kW as W")
        self.assertIn("once, if the next try still shows kW as W", out)
        self.assertIn("t: allowed once, if the next try still shows kW as W: divide by 1000",
                      run_wb("coding"))
        os.environ["FAKE_SCENARIO"] = "ok"
        run_wb("feedback", "t", "--text", "one more try")            # the try it was granted for
        wait_phase("t", {"review"})
        self.assertIn("took over t", run_wb("takeover", "t"))        # still there: not spent
        f = store.Task("t").dir / "coding.json"
        rows = json.loads(f.read_text())["allowed"]
        f.write_text(json.dumps({"allowed": [{**rows[0], "started": 1}]}))   # the mod, at Claude's edit
        out = run_wb("coding", "used", "t", "--did", "power.py: watts = raw / 1000")
        self.assertIn("Hand the testing back to the agent: wb feedback t", out)
        run_wb("feedback", "t", "--text", "I fixed the units; check the tests")
        wait_phase("t", {"review"})
        row = json.loads(f.read_text())["allowed"][0]
        self.assertEqual(row["did"], "power.py: watts = raw / 1000")   # what it changed, kept
        self.assertEqual(self.refused("takeover", "t")[0], 3)        # used up
        self.assertIn("Only when I say", run_wb("coding"))           # the slider never moved
        self.start("t2", "ok")                                       # nor does the next task get it
        wait_phase("t2", {"review"})
        self.assertEqual(self.refused("takeover", "t2")[0], 3)
        self.assertEqual(self.refused("coding", "used", "t2", "--did", "x")[0], 1)

    def test_only_when_i_say_keeps_the_work_local_but_the_users_hand_back_still_works(self):
        run_wb("coding", "only")
        self.start("t", "ok")
        wait_phase("t", {"review"})
        code, err = self.refused("takeover", "t")
        self.assertEqual(code, 3)
        self.assertIn("report the blocker to the user", err)
        self.assertEqual(self.refused("takeover", "--all")[0], 3)
        self.assertIn("took over t", run_wb("takeover", "--all", "--user"))   # /workbench-quit-and-hand-back
        self.assertIn("the user handed it to Claude", run_wb("coding"))     # so the mod lets Claude edit
        self.assertIn("Only when I say", run_wb("coding"))           # kept: a restart reads it again
        self.assertEqual(self.refused("coding", "allow", "t", "--edit", "x")[0], 1)  # needs their words

    def test_takeover_all_says_each_refusal_and_still_takes_over_the_rest(self):
        # #601 (the audit of v1.90): the first refused task exited 3 before any runner was stopped
        run_wb("coding", "only")
        for name in ("t", "t2"):
            self.start(name, "ok")
            wait_phase(name, {"review"})
        run_wb("coding", "allow", "t2", "--edit", "fix the units", "--said", "yes")
        out, err = io.StringIO(), io.StringIO()
        with self.assertRaises(SystemExit) as e, redirect_stdout(out), redirect_stderr(err):
            cli.main(["takeover", "--all"])
        self.assertEqual(e.exception.code, 3)
        self.assertIn("report the blocker to the user", err.getvalue())   # t's refusal, said
        self.assertIn("took over t2", out.getvalue())                     # and t2 still taken
        self.assertEqual(store.Task("t2").status["last"], "Claude took over")
        self.assertNotEqual(store.Task("t").status["last"], "Claude took over")

    def test_takeover_all_skips_a_task_not_checked_out_and_exits_zero_for_the_rest(self):
        # #918: a task still checking out (or failed at checkout) was a refusal: the hand-back
        # exited 1, and the mod queued no turn for the task whose agent it had just stopped
        self.start("t", "ok")
        wait_phase("t", {"review"})
        nc = store.Task("t-nc")
        nc.dir.mkdir(parents=True)
        store.write_json(nc.dir / "task.json", {"name": "t-nc", "checkout": "runner",
                                                "repo": str(self.repo), "cwd": os.getcwd(),
                                                "created_at": store.now()})
        nc.set_status(phase="failed", round=1)
        out = run_wb("takeover", "--all", "--user")       # no SystemExit: exit 0
        self.assertIn("took over t", out)
        self.assertIn("not ready: t-nc (its checkout hasn't finished): wait for it, "
                      "or wb discard t-nc", out)
        self.assertEqual(store.Task("t").status["last"], "Claude took over")
        self.assertFalse(store.Task("t-nc").status.get("taken_over"))

    def test_the_skills_no_mod_hand_back_command_passes_user_so_the_coding_gate_lets_it(self):
        # #601: SKILL.md's hand-back command had no --user and exited 3 under "Only when I say"
        skill = (Path(__file__).parent.parent / "skill/workbench/SKILL.md").read_text()
        cmd = re.search(r"`wb (takeover --all[^`]*)`", skill)
        self.assertIn("--user", cmd.group(1).split())
        run_wb("coding", "only")
        self.start("t", "ok")
        wait_phase("t", {"review"})
        argv = [w for w in cmd.group(1).split() if w.startswith("--") and w not in ("--repo", "--session")]
        self.assertIn("took over t", run_wb("takeover", *argv))


class Verify(Base):
    """wb verify: a regression test on the base and on the candidate (#96)."""
    def setUp(self):
        Base.setUp(self)  # not super(): Shot borrows this setUp
        (self.repo / "calc.py").write_text("def kw(watts):\n    return watts\n")    # the bug
        subprocess.run(["git", "-C", str(self.repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(self.repo), "commit", "-qm", "calc"], check=True)
        self.start("t", "ok")
        wait_phase("t", {"review"})
        self.wt = store.Task("t").worktree
        (self.wt / "calc.py").write_text("def kw(watts):\n    return watts / 1000\n")   # the fix
        (self.wt / "tests").mkdir()
        (self.wt / "tests" / "__init__.py").write_text("")
        (self.wt / "tests" / "test_calc.py").write_text(
            "import unittest\nfrom calc import kw\n\n\nclass T(unittest.TestCase):\n"
            "    def test_kw(self):\n        self.assertEqual(kw(250000), 250)\n")

    def test_a_proven_fix_fails_on_the_base_and_passes_on_the_candidate_touching_neither(self):
        before = (gitops.mark(self.wt), gitops.changed(self.repo))
        out = run_wb("verify", "t", "--test", "python3 -m unittest tests.test_calc")
        self.assertIn("(tests/__init__.py, tests/test_calc.py): proven: it fails on the base", out)
        self.assertIn("base: exit 1: AssertionError: 250000 != 250", out)
        self.assertIn("candidate: exit 0", out)
        self.assertEqual((gitops.mark(self.wt), gitops.changed(self.repo)), before)  # neither touched
        from workbench import verify
        r = verify.last(store.Task("t"))
        self.assertEqual((r["verdict"], r["stale"]), ("proven", False))
        self.assertIn("AssertionError", Path(r["dir"], "base.txt").read_text())   # both outputs kept
        (self.wt / "calc.py").write_text("def kw(watts):\n    return watts // 1000\n")
        self.assertTrue(verify.last(store.Task("t"))["stale"])     # the candidate moved on since

    def test_verify_runs_the_big_text_file_accept_lands_and_proves_nothing_without_a_binary_it_lands(self):
        # #642 (Codex's audit of 1.90.6): the review snapshot's size limit also made verify's
        # candidate, so a 1,100,000-byte text file was left out, verify said proven, and accept
        # landed the file without a word: the same test failed on main
        from workbench import verify
        (self.wt / "big.txt").write_text("bad\n" + "x" * 1_099_996)
        (self.wt / "tests" / "test_calc.py").write_text(
            "import os, unittest\nfrom calc import kw\n\n\nclass T(unittest.TestCase):\n"
            "    def test_kw(self):\n        self.assertEqual(kw(250000), 250)\n\n"
            "    def test_big(self):\n        if os.path.exists('big.txt'):\n"
            "            self.assertEqual(open('big.txt').readline(), 'ok\\n')\n")
        test = "python3 -m unittest tests.test_calc"
        r = subprocess.run(shlex.split(test), cwd=self.wt, capture_output=True,
                           env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"})
        self.assertEqual(r.returncode, 1)                     # the task's checkout fails it
        out = run_wb("verify", "t", "--test", test)
        self.assertIn("the candidate fails it", out)
        result = verify.last(store.Task("t"))
        self.assertIn("big.txt", gitops.git(self.wt, "ls-tree", "--name-only", result["tree"]))
        self.assertFalse(result["stale"])
        self.assertEqual(verify.note(store.Task("t")),
                         f"note: the last regression check (`{test}`) is the candidate fails it")
        # what accept refuses without --include and lands with it: never proof
        (self.wt / "big.txt").write_text("ok\n" + "x" * 1_099_996)
        (self.wt / "blob.bin").write_bytes(b"\0" * gitops.BINARY_MAX)
        out = run_wb("verify", "t", "--test", test)
        self.assertIn("inconclusive", out)
        self.assertIn("lands them with it): blob.bin (1 MB)", out)
        (self.wt / "blob.bin").unlink()
        self.assertIn("proven: it fails on the base", run_wb("verify", "t", "--test", test))
        self.assertEqual(verify.note(store.Task("t")), "")

    def test_a_failing_test_swapped_for_a_passing_one_with_no_code_change_is_not_proven(self):
        # #643 (Codex's audit of 1.90.6): the base overlay borrowed the candidate's new test but
        # kept the one it deleted, so `unittest discover` ran the failing test_old.py on the base
        # and only the passing test_new.py on the candidate, and verify said proven, citing the
        # deleted test's assertion, with calc.py unchanged
        from workbench import verify
        run_wb("discard", "t")
        (self.repo / "test_old.py").write_text(
            "import unittest\nfrom calc import kw\n\n\nclass T(unittest.TestCase):\n"
            "    def test_kw(self):\n        self.assertEqual(kw(250000), 250)\n")
        subprocess.run(["git", "-C", str(self.repo), "add", "-A"], check=True)
        subprocess.run(["git", "-C", str(self.repo), "commit", "-qm", "a failing test"], check=True)
        self.start("t2", "ok")
        wait_phase("t2", {"review"})
        wt = store.Task("t2").worktree
        (wt / "test_old.py").unlink()
        (wt / "test_new.py").write_text(
            "import unittest\nfrom calc import kw\n\n\nclass T(unittest.TestCase):\n"
            "    def test_zero(self):\n        self.assertEqual(kw(0), 0)\n")
        out = run_wb("verify", "t2", "--test", "python3 -m unittest discover")
        self.assertIn("not proven: it already passes on the base", out)
        r = verify.last(store.Task("t2"))
        self.assertEqual((r["verdict"], r["files"], r["removed"]),
                         ("base-passes", ["test_new.py"], ["test_old.py"]))
        # renamed away and made to pass: the old name goes from the base too
        (wt / "test_new.py").unlink()
        (wt / "test_renamed.py").write_text((self.repo / "test_old.py").read_text()
                                            .replace("kw(250000), 250", "kw(0), 0"))
        self.assertIn("already passes on the base",
                      run_wb("verify", "t2", "--test", "python3 -m unittest discover"))

    def test_a_killed_verify_leaves_no_scratch_clone_and_no_test_running(self):
        # #372 (the audit of 1.6): Claude's Bash killed wb verify at 2 minutes, and its clone and
        # the test (in a session of its own) were left behind
        marker = f"sleep {3000 + os.getpid() % 1000}"
        proc = subprocess.Popen([str(ROOT / "bin" / "wb"), "verify", "t", "--test", marker],
                                stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        def running():
            return subprocess.run(["pgrep", "-f", f"^{marker}$"], capture_output=True).returncode == 0
        end = time.monotonic() + 60
        while not running() and time.monotonic() < end:
            time.sleep(0.1)
        self.assertTrue(running(), "the test never started")
        self.assertTrue(list(store.home().glob(".verify-*")))
        proc.terminate()
        self.assertEqual(proc.wait(30), 128 + signal.SIGTERM)
        self.assertFalse(running())
        self.assertEqual(list(store.home().glob(".verify-*")), [])

    def test_verify_and_shot_after_steps_that_changed_nothing_compare_with_the_last_commit(self):
        # #652 (Claude's and Codex's audits): a wb next step with no changes made no commit, so
        # the step after it found no "(step N)" trailer and wb verify and wb shot died with
        # "cannot find the last approved step's commit"
        from workbench import verify
        task = store.Task("t")
        nxt = lambda: run_wb("next", "t", "--spec", str(self.spec), "-m", "Step")  # noqa
        self.assertIn("committed as", nxt())                       # step 1: the fix
        wait_phase("t", {"review"})
        step1 = gitops.git(self.wt, "rev-parse", "HEAD").strip()
        for clean in (3, 4):                                       # one, then two clean steps
            self.assertIn("had no changes", nxt())
            wait_phase("t", {"review"})
            self.assertEqual(task.status["steps"], clean)
            self.assertEqual(task.status["step_base"], step1)
            (self.wt / "tests/test_again.py").write_bytes((self.wt / "tests/test_calc.py").read_bytes())
            out = run_wb("verify", "t", "--test", "python3 -m unittest tests.test_again")
            self.assertIn("already passes", out)
            self.assertEqual(verify.last(task)["base"]["rev"], step1)
            self.assertFalse(verify.last(task)["stale"])
            shot = run_wb("shot", "t", "--capture", TRUE)
            self.assertIn(f"base {step1[:10]}", shot)
            (self.wt / "tests/test_again.py").unlink()
        task.set_status(step_base=None)  # a task from before the record: the walk back finds it
        self.assertEqual(verify._review_base(task), step1)

    def test_verify_credits_the_step_that_fixed_the_bug(self):
        # #252 (the audit of 1.2): step two's test passed on step one's commit already.
        from workbench import verify
        task = store.Task("t")
        run_wb("verify", "t", "--test", "python3 -m unittest tests.test_calc")
        with mock.patch("sys.stdin", io.StringIO("Document the conversion.")):
            run_wb("next", "t", "--spec", "-", "-m", "Fix conversion")
        wait_phase("t", {"review"})
        self.assertTrue(verify.last(task)["stale"])
        approved = gitops.git(self.wt, "rev-parse", "HEAD").strip()
        (self.wt / "tests/test_again.py").write_bytes((self.wt / "tests/test_calc.py").read_bytes())
        out = run_wb("verify", "t", "--test", "python3 -m unittest tests.test_again")
        result = verify.last(task)
        self.assertEqual(result["files"], ["tests/test_again.py"])
        self.assertEqual(result["verdict"], "base-passes")
        self.assertEqual(result["base"]["rev"], approved)
        self.assertEqual(result["candidate"]["rev"], gitops.snapshot(self.wt))
        self.assertIn(approved, out)
        self.assertIn(result["candidate"]["rev"], out)
        self.assertIn("already passes", out)

    def test_a_test_that_passes_on_the_base_or_fails_to_set_up_proves_nothing(self):
        (self.wt / "tests" / "test_calc.py").write_text(
            "import unittest\nfrom calc import kw\n\n\nclass T(unittest.TestCase):\n"
            "    def test_kw(self):\n        self.assertEqual(kw(0), 0)\n")
        self.assertIn("not proven: it already passes on the base",
                      run_wb("verify", "t", "--test", "python3 -m unittest tests.test_calc"))
        (self.wt / "units.py").write_text("K = 1000\n")                # new on the candidate only
        (self.wt / "tests" / "test_calc.py").write_text(
            "import unittest\nfrom units import K\n\n\nclass T(unittest.TestCase):\n"
            "    def test_k(self):\n        self.assertEqual(K, 1000)\n")
        out = run_wb("verify", "t", "--test", "python3 -m unittest tests.test_calc")
        self.assertIn("inconclusive: the base run didn't fail on an assertion", out)  # a missing module
        out = run_wb("verify", "t", "--test", "sleep 5", "--timeout", "1", "--files", "tests/test_calc.py")
        self.assertIn("inconclusive", out)
        self.assertIn("base: exit timeout", out)
        (self.wt / "calc.py").write_text("def kw(watts):\n    return watts\n")
        (self.wt / "tests" / "test_calc.py").write_text(
            "import unittest\nfrom calc import kw\n\n\nclass T(unittest.TestCase):\n"
            "    def test_kw(self):\n        self.assertEqual(kw(250000), 250)\n")
        self.assertIn("the candidate fails it",
                      run_wb("verify", "t", "--test", "python3 -m unittest tests.test_calc"))

    def test_only_an_assertion_or_the_named_failure_proves_a_regression(self):
        # #193 (the 2026-11-19 audit): Python's `SyntaxError: expected ':'` matched "expected", and
        # a base that never ran an assertion was called proven
        from workbench import verify
        self.assertEqual(verify.verdict(1, "  def f()\n         ^\nSyntaxError: expected ':'", 0),
                         "inconclusive")
        self.assertEqual(verify.verdict(1, "ModuleNotFoundError: No module named 'units'", 0),
                         "inconclusive")
        self.assertEqual(verify.verdict(1, "FAIL\texample.com/x [build failed]", 0), "inconclusive")
        self.assertEqual(verify.verdict(1, "--- FAIL: TestKw (0.00s)\n    kw_test.go:9: expected 250, got 250000", 0),
                         "proven")                                          # the positive control
        self.assertEqual(verify.verdict(1, "E       assert 250000 == 250", 0), "proven")
        # #326 (the audit of 1.4, reproduced): the traceback quoted the line that didn't parse
        self.assertEqual(verify.verdict(1, '  File "calc.py", line 3\n    assert 2 = 2\n           ^\n'
                                           "SyntaxError: cannot assign to literal", 0), "inconclusive")
        out = run_wb("verify", "t", "--test", "python3 -m unittest tests.test_calc",
                     "--expect", "250000 != 250")
        self.assertIn("proven", out)
        out = run_wb("verify", "t", "--test", "python3 -m unittest tests.test_calc",
                     "--expect", "a failure it never prints")
        self.assertIn("inconclusive", out)

    def test_a_test_calling_an_api_only_the_candidate_has_proves_nothing(self):
        # #729 (the 2026-11-21 audit, reproduced): pytest quoted the failing source line, `>
        # assert mod.slugify(…)`, which matched ASSERTION, and jest's `is not a function` came
        # under a ✕ header: a test showing only that the API was missing was called proven
        from workbench import verify
        pytest = ("    def test_slug():\n>       assert mod.slugify('A B') == 'a-b'\n"
                  "E       AttributeError: module 'mod' has no attribute 'slugify'\n\n"
                  "tests/test_slug.py:4: AttributeError\n"
                  "FAILED tests/test_slug.py::test_slug - AttributeError: module 'mod' has no attri…\n")
        jest = ("FAIL src/slug.test.js\n  ✕ slugifies (2 ms)\n\n"
                "    TypeError: (0 , _slug.slugify) is not a function\n")
        cases = [pytest, jest,
                 "E       TypeError: split() got an unexpected keyword argument 'sep'",
                 "E       TypeError: parse() takes 1 positional argument but 2 were given",
                 "E       NameError: name 'slugify' is not defined",
                 "    expect(slugify('A B')).toBe('a-b')\n    ReferenceError: slugify is not defined",
                 "  ✕ adds\n    NoMethodError: undefined method `slugify' for Slug:Class",
                 # pytest's first error not an assertion's: the test never got to check the bug
                 ">       assert parse(x) == 3\nE       KeyError: 'x'\n"]
        for out in cases:
            self.assertEqual(verify.verdict(1, out, 0), "inconclusive", out)
        self.assertEqual(verify.assertion(pytest),
                         "E       AttributeError: module 'mod' has no attribute 'slugify'")
        # the positive controls: pytest's own assertion, and its pytest.raises
        self.assertEqual(verify.verdict(1, ">       assert slug('A B') == 'a-b'\n"
                                           "E       AssertionError: assert 'A B' == 'a-b'\n", 0), "proven")
        self.assertEqual(verify.verdict(1, ">       with pytest.raises(ValueError):\n"
                                           "E       Failed: DID NOT RAISE <class 'ValueError'>\n", 0), "proven")
        self.assertEqual(verify.verdict(1, "FAIL src/slug.test.js\n  ✕ slugifies\n"
                                           "    Expected: \"a-b\"\n    Received: \"A B\"\n", 0), "proven")

    def test_phpunit_xctest_swift_testing_catch2_and_bats_failures_are_proven(self):
        # #730 (the 2026-11-21 audit, reproduced): none of these runners' failures matched
        # ASSERTION or FAILED_TEST, so their genuine regressions were inconclusive
        from workbench import verify
        runs = {
            "phpunit": ("There was 1 failure:\n\n1) SlugTest::testSlug\nFailed asserting that two "
                        "strings are identical.\n--- Expected\n+++ Actual\n\nFAILURES!\n"
                        "Tests: 1, Assertions: 1, Failures: 1.\n"),
            "pest": "   FAILED  Tests\\Unit\\SlugTest > slugifies\n  Failed asserting that 'A B' is identical to 'a-b'.\n",
            "xctest": ("/src/Tests/SlugTests/SlugTests.swift:5: error: -[SlugTests.SlugTests testSlug] : "
                       "XCTAssertEqual failed: (\"A B\") is not equal to (\"a-b\")\n"
                       "Test Case '-[SlugTests.SlugTests testSlug]' failed (0.001 seconds).\n"),
            "swift-testing": ("✘ Test slugifies() recorded an issue at SlugTests.swift:5:3: "
                              "Expectation failed: (slug(\"A B\") → \"A B\") == \"a-b\"\n"
                              "✘ Test slugifies() failed after 0.001 seconds with 1 issue.\n"),
            "catch2": ("-------------------------------------------------------------------------------\n"
                       "slugifies\n------------------------------------------------------------------------------\n"
                       "/src/test.cpp:5\n...............................................................................\n\n"
                       "/src/test.cpp:5: FAILED:\n  REQUIRE( slug(\"A B\") == \"a-b\" )\nwith expansion:\n"
                       "  \"A B\" == \"a-b\"\n"),
            "bats": ("1..1\nnot ok 1 slugifies\n# (in test file test/slug.bats, line 4)\n"
                     "#   `[ \"$output\" = \"a-b\" ]' failed\n"),
        }
        for runner_name, out in runs.items():
            self.assertEqual(verify.verdict(1, out, 0), "proven", runner_name)
            self.assertTrue(verify.assertion(out), runner_name)
        # the same runners when what failed is missing, not wrong: still no proof
        for out in ("1..1\nnot ok 1 slugifies\n# test/slug.bats: line 3: slugify: command not found\n",
                    "1) SlugTest::testSlug\nError: Call to undefined function slugify()\n\nERRORS!\n",
                    "1) SlugTest::testSlug\nError: Call to undefined method Slug::slugify()\n"):
            self.assertEqual(verify.verdict(1, out, 0), "inconclusive", out)
        # and the wording no longer assumes the setup failed
        self.assertIn("output it doesn't read, which --expect TEXT can name", verify.SAY["inconclusive"])

    def test_a_golden_file_the_candidate_adds_goes_to_the_base_and_one_left_out_proves_nothing(self):
        # #500 (the audit of 1.90): Go's testdata/ wasn't copied to the base, which failed on
        # `open testdata/case1.golden: no such file or directory`, and that was called proven
        from workbench import verify
        golden = "parse/testdata/case1.golden"
        (self.wt / "parse" / "testdata").mkdir(parents=True)
        (self.wt / golden).write_text("250\n")
        (self.wt / "tests" / "test_golden.py").write_text(
            "import unittest\nfrom calc import kw\n\n\nclass T(unittest.TestCase):\n"
            "    def test_kw(self):\n"
            f"        assert kw(250000) == int(open('{golden}').read()), 'not the golden value'\n")
        out = run_wb("verify", "t", "--test", "python3 -m unittest tests.test_golden")
        r = verify.last(store.Task("t"))
        self.assertIn(golden, r["files"])                         # the data, with the test
        self.assertEqual(r["verdict"], "proven", out)
        base = Path(r["dir"], "base.txt").read_text()
        self.assertIn("not the golden value", base)               # failed on the bug, not the file
        self.assertNotIn("FileNotFoundError", base)
        # named with --files, the data left behind: the base fails for lack of it, not the bug
        out = run_wb("verify", "t", "--test", "python3 -m unittest tests.test_golden",
                     "--files", "tests/test_golden.py")
        self.assertIn("inconclusive", out)
        self.assertIn(f"the base lacked what the candidate adds: {golden}", out)
        # Go's own words, from the issue's reproduction
        go = ("--- FAIL: TestParse (0.00s)\n    parse_test.go:12: open testdata/case1.golden: "
              "no such file or directory\nFAIL\nexample.com/m/parse\t0.002s")
        self.assertEqual(verify.verdict(1, go, 0, added=[golden]), "inconclusive")
        self.assertEqual(verify.verdict(1, go, 0), "proven")        # nothing added: as before
        for p in ("parse/testdata/x.golden", "fixtures/a.json", "src/fixture/b.txt",
                  "src/__fixtures__/c", "src/__snapshots__/app.test.js.snap", "golden/out.txt",
                  "app.test.js.snap", "tests/x.py", "x_test.go"):
            self.assertTrue(verify.looks_like_test(p), p)
        self.assertFalse(verify.looks_like_test("src/parse.go"))

    def test_a_build_tree_naming_its_checkout_is_made_afresh_in_each_scratch_checkout(self):
        # #424 (the audit of 1.8, reproduced with CMake): the worktree's build/ (configured by the
        # setup, CMAKE_HOME_DIRECTORY the worktree) was copied to the base's checkout, its target
        # ran the candidate's code there, and verify said the test already passed on the base
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        (self.repo / ".gitignore").write_text("build/\n")
        g("add", "-A")
        g("commit", "-qm", "ignore the build tree")
        configure = ('mkdir -p build && printf "CMAKE_HOME_DIRECTORY:INTERNAL=%s\\n" "$PWD" '
                     '> build/CMakeCache.txt && printf "%s" "$PWD" > build/src')
        self.start("t-cmake", "ok", "--queue", "--setup", configure)
        wait_phase("t-cmake", {"review"})
        wt = store.Task("t-cmake").worktree
        for p in ("calc.py", "tests/__init__.py", "tests/test_calc.py"):
            (wt / p).parent.mkdir(exist_ok=True)
            (wt / p).write_bytes((self.wt / p).read_bytes())
        build = 'cd "$(cat build/src)" && python3 -m unittest tests.test_calc'  # as its target runs
        out = run_wb("verify", "t-cmake", "--test", build)
        self.assertIn("test_calc.py): proven", out)              # the base ran the base's code
        # a build tree copied from the user's checkout, with no setup to make it afresh: said
        (self.repo / "build").mkdir()
        (self.repo / "build" / "CMakeCache.txt").write_text(
            f"CMAKE_HOME_DIRECTORY:INTERNAL={self.repo}\n")
        self.start("t-copied", "ok", "--queue", "--copy", "build")
        wait_phase("t-copied", {"review"})
        wt = store.Task("t-copied").worktree
        (wt / "tests").mkdir()
        (wt / "tests" / "test_x.py").write_text("")
        out = run_wb("verify", "t-copied", "--test", "true")
        self.assertIn("inconclusive", out)
        self.assertIn("base: exit setup failed", out)
        said = Path(verify_dir := store.Task("t-copied").dir / "verify" / "1", "base.txt").read_text()
        self.assertIn(f"build is a build tree configured for {self.repo}", said, verify_dir)

    def test_with_unload_for_tests_the_checks_have_the_gpu_alone(self):
        # #502 (the audit of 1.90): the base check, wb verify and wb shot ran the project's GPU
        # tests beside other tasks' resident models, taking no lease and freeing nothing, and an
        # out-of-memory failure read as the base's or the change's
        with mock.patch.object(cli, "spawn_runner"):
            self.start("t-gpu", "ok", "--queue", "--unload-for-tests", "--test", TEST_CMD)
        seen, freed, real = [], [], runner.run_in_lane

        def look(task, cmd, limit):
            seen.append((cmd, runner.models.holders()))
            return real(task, cmd, limit)
        with mock.patch.object(runner, "run_in_lane", side_effect=look), \
                mock.patch.object(runner.models, "free_gpu",
                                  side_effect=lambda *a, **k: freed.append(1)):
            runner.drive(store.Task("t-gpu"))
            wt = store.Task("t-gpu").worktree
            (wt / "tests").mkdir()
            (wt / "tests" / "test_x.py").write_text("")
            run_wb("verify", "t-gpu", "--test", TEST_CMD)
            run_wb("shot", "t-gpu", "--capture", "true")
        me = str(os.getpid())
        checks = [h for cmd, h in seen if TEST_CMD in cmd and "-c" not in cmd]
        base_check, round_tests, base, cand = checks[:4]
        for held in (base_check, base, cand):                       # alone, as no model's task
            self.assertEqual([(p, h["model"], h["task"]) for p, h in held.items()],
                             [(me, None, "t-gpu")])
        # the round's: the model stepped aside, the task still holds the GPU for its tests (#428)
        self.assertEqual([(h["model"], h["task"], h.get("tests")) for h in round_tests.values()],
                         [(None, "t-gpu", True)])
        shots = [h for cmd, h in seen if "WB_SHOT_OUT" in cmd]
        self.assertEqual([list(h) for h in shots], [[me], [me]])
        self.assertEqual(len(freed), 4)          # once each: check, round's tests (#943), verify, shot
        self.assertEqual(runner.models.holders(), {})
        # without the flag, as before: no lease
        seen.clear()
        with mock.patch.object(runner, "run_in_lane", side_effect=look):
            run_wb("verify", "t", "--test", "python3 -m unittest tests.test_calc")
        self.assertEqual([h for _, h in seen], [{}, {}])

    def test_with_unload_for_tests_and_a_remote_model_the_tests_have_this_machines_gpu_alone(self):
        # #943 (an outside review of 1.90.24): with the model on a wb remote box, the round's
        # tests let go of the box's pool and took nothing here, and verify.gpu returned at once
        # ("not local"), yet the base check, the round's tests, wb verify and wb shot all run on
        # this machine's GPU, beside a local task's model or a wb image job
        models = runner.models
        cfg = json.loads(Path(os.environ["WB_OPENCODE_CONFIG"]).read_text())
        cfg["provider"]["ollama-pc"] = {"options": {"baseURL": "http://gpu-pc.invalid:11434/v1"},
                                        "models": {"coder": {"limit": {"context": 32768}}}}
        Path(os.environ["WB_OPENCODE_CONFIG"]).write_text(json.dumps(cfg))
        Path(os.environ["WB_MODELS"]).write_text(json.dumps({"ollama-pc": {"local": True}}))
        box = models.discover()["ollama-pc/coder"]
        self.assertNotEqual(models.pool(box), "gpu")
        with mock.patch.object(cli, "spawn_runner"):
            self.start("t-gpu", "ok", "--queue", "--unload-for-tests", "--test", TEST_CMD,
                       "--model", box.id)
        seen, real = [], runner.run_in_lane

        def look(task, cmd, limit):
            seen.append((cmd, models.holders(), models.holders(pool=models.pool(box))))
            return real(task, cmd, limit)
        with mock.patch.object(runner, "run_in_lane", side_effect=look):
            runner.drive(store.Task("t-gpu"))
            wt = store.Task("t-gpu").worktree
            (wt / "tests").mkdir()
            (wt / "tests" / "test_x.py").write_text("")
            run_wb("verify", "t-gpu", "--test", TEST_CMD)
        checks = [(h, there) for cmd, h, there in seen if TEST_CMD in cmd and "-c" not in cmd]
        self.assertEqual(len(checks), 4)                 # the base check, the round's, base, candidate
        local = next(o for o in models.discover().values() if not o.remote)
        for held, there in checks:
            self.assertEqual([(p, h["model"], h["task"]) for p, h in held.items()],
                             [(str(os.getpid()), None, "t-gpu")])       # this GPU, alone
            self.assertFalse(models.admits(None, held))                  # wb image waits
            self.assertFalse(models.admits(local, held))                 # and a local task
        self.assertEqual(checks[1][1], {})                               # the box let go meanwhile
        self.assertEqual(models.holders(), {})
        self.assertEqual(store.Task("t-gpu").status["phase"], "review")

    def test_a_base_check_waiting_for_the_gpu_holds_no_prep_turn_meanwhile(self):
        # #679 (Claude's audit of main): an --unload-for-tests base check took the machine's one
        # prep turn and then waited inside it for the GPU, behind another task's whole run, so
        # every queued task's setup and base check waited too
        from workbench import media, verify
        with mock.patch.object(cli, "spawn_runner"):
            self.start("t-gpuwait", "ok", "--queue", "--unload-for-tests", "--test", TEST_CMD)
        order = []

        def held(name):
            @contextlib.contextmanager
            def cm(*_, **__):
                order.append(name)
                yield
                order.append("/" + name)
            return cm
        with mock.patch.object(media, "gpu", held("gpu")), \
                mock.patch.object(runner, "prep_turn", held("turn")), \
                mock.patch.object(verify, "_run", side_effect=lambda *a: order.append("run") or (1, "x")):
            runner._base_check(store.Task("t-gpuwait"))
        self.assertEqual(order, ["gpu", "turn", "run", "/turn", "/gpu"])
        self.assertEqual(store.Task("t-gpuwait").status["base_check"]["exit"], 1)

    def test_the_scratch_checkouts_read_the_bytes_the_task_reads(self):
        # #426 (the audit of 1.8, reproduced): with the repo's own core.autocrlf the task read
        # CRLF, and the base check's and verify's clones read LF, failing on an untouched file
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        (self.repo / "data.txt").write_bytes(b"a\nb\n")
        (self.repo / "more.dat").write_bytes(b"x\ny\n")
        g("add", "-A")
        g("commit", "-qm", "data")
        g("config", "core.autocrlf", "true")
        (self.repo / ".git" / "info" / "attributes").write_text("*.dat -text\n")  # kept as is
        check = ("python3 -c \"import sys; ok = open('data.txt', 'rb').read() == b'a\\r\\nb\\r\\n' "
                 "and open('more.dat', 'rb').read() == b'x\\ny\\n'; sys.exit(0 if ok else 3)\"")
        self.start("t-crlf", "ok", "--queue", "--test", check)
        st = wait_phase("t-crlf", {"review"})
        wt = store.Task("t-crlf").worktree
        self.assertEqual((wt / "data.txt").read_bytes(), b"a\r\nb\r\n")    # the task's bytes
        self.assertEqual((wt / "more.dat").read_bytes(), b"x\ny\n")
        self.assertTrue(st["base_check"]["ok"], st["base_check"])          # the base check's
        (wt / "tests").mkdir()
        (wt / "tests" / "test_x.py").write_text("")
        run_wb("verify", "t-crlf", "--test", check)
        from workbench import verify
        r = verify.last(store.Task("t-crlf"))
        self.assertEqual((r["base"]["exit"], r["candidate"]["exit"]), (0, 0))  # and verify's

    def test_the_scratch_checkouts_run_the_repos_own_filters_and_say_when_they_cant(self):
        # #932 (an outside review of v1.90.24, reproduced): a clone has none of the repo's local
        # config, so a file under a local clean/smudge filter (git-crypt, transcrypt) checked out
        # as the stored blob there, and the base check failed on an unchanged file
        from workbench import verify
        g = lambda *a: subprocess.run(["git", "-C", str(self.repo), *a], check=True)  # noqa
        g("config", "filter.swap.clean", "sed s/EXPANDED/STORED/")
        g("config", "filter.swap.smudge", "sed s/STORED/EXPANDED/")
        (self.repo / ".gitattributes").write_text("fixture.txt filter=swap\n")
        (self.repo / "fixture.txt").write_text("EXPANDED\n")
        g("add", "-A")
        g("commit", "-qm", "a filtered fixture")
        self.assertEqual(gitops.git(self.repo, "cat-file", "-p", "HEAD:fixture.txt"), "STORED\n")
        check = "grep -q EXPANDED fixture.txt"
        self.start("t-swap", "ok", "--queue", "--test", check)
        st = wait_phase("t-swap", {"review"})
        wt = store.Task("t-swap").worktree
        self.assertEqual((wt / "fixture.txt").read_text(), "EXPANDED\n")   # the task's bytes
        self.assertTrue(st["base_check"]["ok"], st["base_check"])           # the base check's
        (wt / "tests").mkdir()
        (wt / "tests" / "test_x.py").write_text("")
        run_wb("verify", "t-swap", "--test", check)
        r = verify.last(store.Task("t-swap"))
        self.assertEqual((r["base"]["exit"], r["candidate"]["exit"]), (0, 0))  # and verify's
        clone = Path(self.tmp.name) / "bench-like"                          # and bench's
        gitops.scratch_clone(self.repo, clone)
        verify.checkout_settings(self.repo, clone)
        gitops.git(clone, "checkout", "-q", "--detach", "HEAD")
        self.assertEqual((clone / "fixture.txt").read_text(), "EXPANDED\n")
        # a filter whose state the clone lacks (git-crypt's keys): said, not "fails on the base"
        g("config", "filter.swap.smudge",
          "sh -c 'case $(pwd -P) in *.verify-*) cat ;; *) sed s/STORED/EXPANDED/ ;; esac'")
        self.start("t-swap2", "ok", "--queue", "--test", check)
        st = wait_phase("t-swap2", {"review"})
        self.assertEqual(st["base_check"]["exit"], "filtered", st["base_check"])
        line = runner.base_check_line(st["base_check"], store.Task("t-swap2"))
        self.assertIn("the base wasn't checked: fixture.txt checks out differently", line)
        self.assertIn("filter.swap", line)
        self.assertNotIn("fails", line)
        # a required one that fails there: the checkout's failure, named
        g("config", "filter.swap.required", "true")
        g("config", "filter.swap.smudge",
          "sh -c 'case $(pwd -P) in *.verify-*) exit 1 ;; *) sed s/STORED/EXPANDED/ ;; esac'")
        code, out = verify.on_base(store.Task("t-swap2"), check, 60)
        self.assertEqual(code, "filtered")
        self.assertIn("failed in filter.swap", out)

