        run_wb("discard", "t-loop")
        row = store.results()[-1]
        self.assertEqual(row["guards"], {"repeat": 1})
        self.assertEqual(row["started_at"], store.Task("t-loop").spec["created_at"])
        self.assertIn("load_secs", row)

