    def test_a_retried_send_lands_once(self):
        tok = self.chat.token()
        a = self.call("/api/send", {"text": "hi", "cid": "c-1"}, token=tok)[1]
        b = self.call("/api/send", {"text": "hi", "cid": "c-1"}, token=tok)[1]
        self.assertEqual(a["message"]["id"], b["message"]["id"])
        self.assertEqual(len(b["state"]["messages"]), 1)
        self.assertEqual(self.call("/api/send", {"text": "x", "cid": 7}, token=tok)[0], 400)

    def test_a_send_cut_off_at_any_point_reaches_the_listener_exactly_once_when_retried(self):
        # #446 (the 2026-11-20 audit): cut off after the message was appended and before the open
        # index had it, the retry found the client id and said sent; the thread showed it and the
        # listener never had it
        chat = self.chat
        pending = lambda: [r["id"] for r in chat.pending()]
        with mock.patch.object(chat.store, "append_jsonl", side_effect=OSError("cut")):  # before the append
            with self.assertRaises(OSError):
                chat.send("one", "user", "c-a")
        a = chat.send("one", "user", "c-a")
        self.assertEqual(pending(), [a["id"]])
        with mock.patch.object(chat, "_open_update", side_effect=OSError("cut")):  # between the two
            with self.assertRaises(OSError):
                chat.send("two", "user", "c-b")
        self.assertEqual(pending(), [a["id"]])
        b = chat.send("two", "user", "c-b")
        self.assertEqual(pending(), [a["id"], b["id"]])
        self.assertEqual(chat.send("two", "user", "c-b")["id"], b["id"])  # after both: nothing new
        self.assertEqual(pending(), [a["id"], b["id"]])
        chat.ack(b["id"], "s")                                             # Claude has it: a late retry
        self.assertEqual(chat.send("two", "user", "c-b")["id"], b["id"])  # doesn't send it again
        self.assertEqual(pending(), [a["id"]])
        rows = store.read_jsonl(chat.chat_dir() / "messages.jsonl")[0]
        self.assertEqual([r["cid"] for r in rows], ["c-a", "c-b"])

    def test_a_send_retried_after_many_messages_still_lands_once(self):
        # #199 (the 2026-11-19 audit): only the last 500 rows were checked for the client id, so a
        # tab offline longer than that sent its queued message twice
        tok = self.chat.token()
        first = self.call("/api/send", {"text": "queued offline", "cid": "old-1"}, token=tok)[1]
        with open(self.chat.chat_dir() / "messages.jsonl", "a") as f:
            for i in range(800):
                f.write(json.dumps({"id": f"m{i}", "ts": 1, "from": "claude", "text": "x", "cid": f"c{i}"}) + "\n")
        again = self.call("/api/send", {"text": "queued offline", "cid": "old-1"}, token=tok)[1]
        self.assertEqual(again["message"]["id"], first["message"]["id"])
        rows = store.read_jsonl(self.chat.chat_dir() / "messages.jsonl")[0]
        self.assertEqual(sum(r.get("cid") == "old-1" for r in rows), 1)

    def test_wb_chat_on_never_shows_a_link_to_another_programs_server(self):
        # #200 (the 2026-11-19 audit): a bare connect counted any program on the port as the chat,
        # and a started server was reported after a fixed half second, up or not
        from http.server import BaseHTTPRequestHandler

        class Other(BaseHTTPRequestHandler):
            def do_GET(self):
                self.send_response(200)
                self.end_headers()

            def log_message(self, *a):
                pass
        other = ThreadingHTTPServer(("127.0.0.1", 0), Other)
        threading.Thread(target=other.serve_forever, daemon=True).start()
        self.addCleanup(other.server_close)
        self.addCleanup(other.shutdown)
        port = other.server_address[1]
        self.assertEqual(self.chat.who_answers(self.port), "workbench")
        self.assertEqual(self.chat.who_answers(port), "other")
        err = io.StringIO()
        with redirect_stderr(err), self.assertRaises(SystemExit):
            run_wb("chat", "on", "--port", str(port))
        self.assertIn(f"or another program, or a server still on a replaced token) answers on port {port}",
                      err.getvalue())
        dead = subprocess.Popen([sys.executable, "-c", "raise SystemExit(1)"])  # a server that dies
        with socket.socket() as sk:
            sk.bind(("127.0.0.1", 0))
            free = sk.getsockname()[1]
        self.assertFalse(self.chat.wait_up(free, dead.pid, limit=5))

    def test_an_ipv6_only_chat_is_seen_running_by_wbs_own_check(self):
        # #450 (the 2026-11-20 audit): `::` was probed at 127.0.0.1, which an IPv6-only socket
        # (bindv6only=1) never answers, so wb chat on took a healthy chat for none
        try:
            with socket.socket(socket.AF_INET6) as sk:
                sk.bind(("::1", 0))
        except OSError:
            self.skipTest("no IPv6 here")
        Path(os.environ["WB_CHAT_CONFIG"]).write_text(json.dumps({"bind": ["::"]}))
        handler = self.srv.RequestHandlerClass
        only6 = type("Only6", (self.chat._Server6,), {"v6only": True})(("::", 0), handler)  # bindv6only=1
        threading.Thread(target=only6.serve_forever, daemon=True).start()
        self.addCleanup(only6.server_close)
        self.addCleanup(only6.shutdown)
        port = only6.server_address[1]
        self.assertFalse(self.chat._connects("0.0.0.0", port))           # nothing on IPv4
        self.assertEqual(self.chat.who_answers(port), "workbench")
        self.assertTrue(self.chat.running(port))

    def test_wb_chat_on_never_takes_another_accounts_chat_for_its_own(self):
        # #554 (the 2026-11-20 audit): the mark said only "a wb chat", so on a shared machine B's
        # wb chat on printed a link to A's server that B's token got 401 on, and off named A's unit
        mine = os.environ["WB_CHAT_TOKEN"]
        os.environ["WB_CHAT_TOKEN"] = str(Path(self.tmp.name) / "a-chat-token")     # account A
        try:
            servers, _ = self.chat.make_servers(0, ["127.0.0.1"])
        finally:
            os.environ["WB_CHAT_TOKEN"] = mine                                     # back to B
        theirs = servers[0]
        threading.Thread(target=theirs.serve_forever, daemon=True).start()
        self.addCleanup(theirs.RequestHandlerClass.hub.close)
        self.addCleanup(theirs.server_close)
        self.addCleanup(theirs.shutdown)
        port = theirs.server_address[1]
        self.assertEqual(self.chat.who_answers(self.port), "workbench")           # B's own
        self.assertEqual(self.chat.who_answers(port), "other")
        self.assertFalse(self.chat.running(port))
        err = io.StringIO()
        with redirect_stderr(err), self.assertRaises(SystemExit):
            run_wb("chat", "on", "--port", str(port))
        self.assertIn(f"another account's chat", err.getvalue())
        self.assertFalse((self.chat.chat_dir() / "serve.pid").exists())           # nothing started
        # #690: the switch stayed on when it died, so the pane read On and pinned a dead link
        self.assertIn("web chat left off", err.getvalue())
        self.assertFalse(self.chat.is_on())
        self.assertEqual(run_wb("chat", "off", "--port", str(port)).strip(), "web chat off")  # no unit named

    def test_a_push_fetches_only_the_newest_open_ask_and_claudes_last_word(self):
        # #755 (the 2026-11-21 audit, finding 102): each push made the service worker fetch the
        # whole /api/state (922 KB with 300 messages and 30 plans) to pick one line
        chat = self.chat
        for i in range(30):
            done = chat.ask("ExitPlanMode", "", "plan", {"plan": f"plan {i}\n" + "step\n" * 4000})
            chat.answer(done["id"], "deny", "web")
        for i in range(100):
            chat.send("x" * 1500, "user" if i % 2 else "claude")
        chat.send("Tests pass, ready for review", "claude")
        chat.send("thanks", "user")
        old = chat.ask("Bash", "rm -rf build")
        plan = chat.ask("ExitPlanMode", "", "plan", {"plan": "1. Read\n" + "2. Write\n" * 3000})
        got = chat.latest()
        self.assertEqual([a["id"] for a in got["asks"]], [plan["id"]])        # the newest open one
        self.assertNotIn("detail", got["asks"][0])                           # not its plan's text
        self.assertEqual([m["text"] for m in got["messages"]], ["Tests pass, ready for review"])
        self.assertLess(len(json.dumps(got)), 2000)
        code, body = self.call("/api/latest", token=chat.token())
        self.assertEqual((code, [a["id"] for a in body["asks"]]), (200, [plan["id"]]))
        self.assertEqual(self.call("/api/latest")[0], 401)
        chat.answer(plan["id"], "allow", "web")
        self.assertEqual([a["id"] for a in chat.latest()["asks"]], [old["id"]])
        self.assertIn("/api/latest", (chat.STATIC / "sw.js").read_text())

    def test_on_macos_the_launchd_agent_is_checked_and_named_instead_of_systemd(self):
        # #756 (the 2026-11-21 audit, finding 103): with the launchd agent keeping the chat up,
        # `wb chat off` and the port-taken error gave systemctl advice, and revive ignored the agent
        chat, ran = self.chat, []
        fake = lambda argv, **kw: ran.append(argv) or subprocess.CompletedProcess(argv, 0, b"", b"")
        with mock.patch.object(chat, "_macos", return_value=True), \
                mock.patch.object(chat.shutil, "which", lambda name: "/bin/" + name), \
                mock.patch.object(chat.subprocess, "run", fake):
            self.assertTrue(chat._unit_keeps_it())
        self.assertEqual(ran, [["launchctl", "print", f"gui/{os.getuid()}/workbench.chat"]])
        with mock.patch.object(chat, "_macos", return_value=True):
            off = run_wb("chat", "off", "--port", str(self.port))              # a server it didn't start
            self.assertIn("launchd's workbench.chat: launchctl bootout gui/$(id -u)/workbench.chat stops it", off)
            self.assertNotIn("systemctl", off)
            with self.assertRaisesRegex(RuntimeError, r"another wb chat serve \(launchctl print "
                                        r"gui/\$\(id -u\)/workbench.chat\)"):
                chat.make_servers(self.port, ["127.0.0.1"])
        with mock.patch.object(chat, "_macos", return_value=False):
            self.assertIn("systemd's wb-chat: systemctl --user disable --now wb-chat stops it",
                          run_wb("chat", "off", "--port", str(self.port)))

    def test_a_chat_wb_chat_on_started_comes_back_after_a_reboot_or_a_crash(self):
        # #449 (the 2026-11-20 audit): the switch stayed on and the pane showed the link, but nothing
        # started the server again, so the phone said "Can't reach the computer" for good
        from workbench import cli
        chat = self.chat
        with socket.socket() as sk:
            sk.bind(("127.0.0.1", 0))
            free = sk.getsockname()[1]
        dead = subprocess.Popen([sys.executable, "-c", "pass"])
        dead.wait()
        chat.set_on(True)
        store.write_json(chat.chat_dir() / "serve.pid", {"pid": dead.pid, "port": free})  # it died
        self.assertIn(f"no server answers on port {free}: wb chat on starts one", cli.chat_gap())
        with mock.patch.object(chat, "_unit_keeps_it", return_value=True):   # systemd's to restart
            self.assertIsNone(chat.revive())
        chat.set_on(False)
        self.assertIsNone(chat.revive())                                       # off: left off
        self.assertIsNone(cli.chat_gap())
        chat.set_on(True)
        with mock.patch.object(chat, "_unit_keeps_it", return_value=False):
            out = run_wb("chat", "url")
        self.assertEqual(out.strip(), f"http://localhost:{free}/#token={chat.token()}")  # the link alone
        pid = store.read_json(chat.chat_dir() / "serve.pid")["pid"]
        self.assertNotEqual(pid, dead.pid)
        try:
            deadline = time.time() + 10
            while not chat.running(free) and time.time() < deadline:
                time.sleep(0.1)
            self.assertTrue(chat.running(free))
            self.assertIsNone(cli.chat_gap())
            self.assertIsNone(chat.revive())                                   # up: not a second
            run_wb("chat", "off", "--port", str(free))
            deadline = time.time() + 10
            while os.waitpid(pid, os.WNOHANG) == (0, 0) and time.time() < deadline:
                time.sleep(0.1)
        finally:
            with contextlib.suppress(ProcessLookupError):
                os.kill(pid, signal.SIGKILL)

    def test_the_launchd_agent_runs_wb_chat_serve_and_keeps_it_up(self):
        # #449: the docs named a launchd agent for macOS and none shipped
        import plistlib
